source:
'use client';
import { useState, useEffect } from 'react';
import { useLocale, useT } from '@/components/LocaleProvider';
import type { TKey } from '@/lib/i18n';
import { CalendarClock, Layers, ShieldCheck, Ticket, Wallet, Banknote, Receipt, Target, CalendarDays, List, LayoutGrid, ChevronLeft, ChevronRight } from 'lucide-react';
import { cur } from '@/lib/money';
import { cn } from '@/components/ui/cn';
import { formatDate, formatTime, formatDateTime } from '@/lib/i18n/format';
import { dayOf } from '@/lib/calendarDay';

export type Kind = 'renewal' | 'installments' | 'bill' | 'payable' | 'income' | 'goal' | 'warranty' | 'voucher';
/** `date` is `YYYY-MM-DD` in the SERVER's frame — the calendar day this entry belongs to, not an
 *  instant. Keep it that way: the moment it becomes a timestamp again, the grid and the labels
 *  start disagreeing with the month block the entry is in. */
export type Entry = { date: string; pinned?: boolean; kind: Kind; label: string; sub: string; amount: number | null };
export type MonthBlock = { key: string; label: string; entries: Entry[]; out: number; inc: number };

const mono = { fontFamily: 'var(--font-mono)' } as const;
const display = { fontFamily: 'var(--font-display)' } as const;

const KIND_META: Record<Kind, { icon: React.ReactNode; color: string; short: string }> = {
  renewal: { icon: <CalendarClock size={15} />, color: 'var(--color-purple)', short: 'renewal' },
  installments: { icon: <Layers size={15} />, color: 'var(--color-gold)', short: 'installments' },
  bill: { icon: <Wallet size={15} />, color: 'var(--color-red)', short: 'bill' },
  payable: { icon: <Receipt size={15} />, color: 'var(--color-orange)', short: 'payable' },
  income: { icon: <Banknote size={15} />, color: 'var(--color-accent)', short: 'income' },
  goal: { icon: <Target size={15} />, color: 'var(--color-purple)', short: 'goal' },
  warranty: { icon: <ShieldCheck size={15} />, color: 'var(--color-cyan)', short: 'warranty' },
  voucher: { icon: <Ticket size={15} />, color: 'var(--color-gold)', short: 'voucher' },
};

type View = 'month' | 'agenda' | 'list';
const VIEWS: { id: View; label: string; icon: React.ReactNode }[] = [
  { id: 'month', label: 'Month', icon: <LayoutGrid size={14} /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays size={14} /> },
  { id: 'list', label: 'List', icon: <List size={14} /> },
];

const fmt = (n: number) => `${cur()}${n.toLocaleString('en-GB')}`;
// `date` is a plain `YYYY-MM-DD` the SERVER chose (see `ymd` in page.tsx) — not an instant.
// `new Date('2026-05-01')` parses it as UTC midnight, so it must be formatted in UTC as well;
// without the timeZone it would be re-read in the viewer's zone and shift back a day for
// everyone west of Greenwich, which is the bug this pair of changes closes.
const dayMonth = (value: string, locale: string) =>
  formatDate(value, locale, { day: 'numeric', month: 'short', timeZone: 'UTC' });



function Amount({ e }: { e: Entry }) {
  if (e.amount == null) return null;
  return (
    <span className={cn('font-bold', e.kind === 'income' && 'text-[color:var(--color-accent)]')} style={display}>
      {e.kind === 'income' ? '+' : ''}{fmt(e.amount)}
    </span>
  );
}

/** One agenda/list row (icon · label/sub · date · amount). */
function EntryRow({ e, showMonth }: { e: Entry; showMonth?: boolean }) {
  const locale = useLocale();
  const meta = KIND_META[e.kind];
  return (
    <div className="flex items-center gap-3 bg-[color:var(--color-surface)] border border-[color:var(--color-border)] rounded-xl px-3.5 py-2.5">
      <span className="grid place-items-center w-8 h-8 rounded-lg shrink-0" style={{ color: meta.color, background: `color-mix(in srgb, ${meta.color} 12%, transparent)` }}>
        {meta.icon}
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium truncate">{e.label}</p>
        <p className="text-[10px] text-[color:var(--color-text-faint)]" style={mono}>{e.sub}</p>
      </div>
      <span className="text-[11px] text-[color:var(--color-text-faint)] shrink-0 w-20 text-right" style={mono}>
        {e.pinned ? 'monthly' : dayMonth(e.date, locale)}
      </span>
      <span className="shrink-0 w-20 text-right text-sm">
        <Amount e={e} />
      </span>
    </div>
  );
}

// ── Month grid ──────────────────────────────────────────────────────────────
const WEEKDAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

function MonthGrid({ month }: { month: MonthBlock }) {
  const [y, mo] = month.key.split('-').map(Number); // mo = 1-12
  const first = new Date(y, mo - 1, 1);
  const firstWeekday = (first.getDay() + 6) % 7; // Mon = 0
  const daysInMonth = new Date(y, mo, 0).getDate();
  const today = new Date();
  const isThisMonth = today.getFullYear() === y && today.getMonth() === mo - 1;

  const pinned = month.entries.filter((e) => e.pinned);
  const byDay = new Map<number, Entry[]>();
  for (const e of month.entries) {
    if (e.pinned) continue;
    const day = dayOf(e.date);
    if (!byDay.has(day)) byDay.set(day, []);
    byDay.get(day)!.push(e);
  }

  const cells: (number | null)[] = [];
  for (let i = 0; i < firstWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);
  while (cells.length % 7 !== 0) cells.push(null);

  return (
    <div>
      {pinned.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-3">
          {pinned.map((e, i) => {
            const meta = KIND_META[e.kind];
            return (
              <span key={i} className="inline-flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-lg border" style={{ ...mono, color: meta.color, borderColor: `color-mix(in srgb, ${meta.color} 40%, transparent)`, background: `color-mix(in srgb, ${meta.color} 10%, transparent)` }}>
                {meta.icon} {e.label}{e.amount != null && <b> {fmt(e.amount)}/mo</b>}
              </span>
            );
          })}
        </div>
      )}

      <div className="grid grid-cols-7 gap-1">
        {WEEKDAYS.map((w) => (
          <div key={w} className="text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-wider text-center pb-1" style={mono}>
            {w}
          </div>
        ))}
        {cells.map((day, i) => {
          const events = day ? byDay.get(day) ?? [] : [];
          const isToday = isThisMonth && day === today.getDate();
          return (
            <div
              key={i}
              className={cn(
                'min-h-[78px] rounded-lg border p-1.5 flex flex-col gap-1',
                day ? 'bg-[color:var(--color-surface)] border-[color:var(--color-border)]' : 'border-transparent',
                isToday && 'ring-1 ring-[color:var(--color-accent)] border-[color:var(--color-accent)]'
              )}
            >
              {day && (
                <span className={cn('text-[11px] font-semibold', isToday ? 'text-[color:var(--color-accent)]' : 'text-[color:var(--color-text-faint)]')} style={mono}>
                  {day}
                </span>
              )}
              {events.map((e, j) => {
                const meta = KIND_META[e.kind];
                return (
                  <span
                    key={j}
                    title={`${e.label} · ${e.sub}${e.amount != null ? ` · ${fmt(e.amount)}` : ''}`}
                    className="text-[10px] leading-tight px-1.5 py-1 rounded truncate"
                    style={{ color: meta.color, background: `color-mix(in srgb, ${meta.color} 14%, transparent)` }}
                  >
                    {e.amount != null && <b>{e.kind === 'income' ? '+' : ''}{fmt(e.amount)} </b>}
                    {e.label}
                  </span>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export function CalendarClient({ months, dueThisMonth }: { months: MonthBlock[]; dueThisMonth: number }) {
  const t = useT();
  const [view, setView] = useState<View>('month');
  const [monthIdx, setMonthIdx] = useState(0);

  useEffect(() => {
    const saved = typeof window !== 'undefined' ? (window.localStorage.getItem('calendarView') as View | null) : null;
    if (saved && VIEWS.some((v) => v.id === saved)) setView(saved);
  }, []);
  function go(v: View) {
    setView(v);
    try { window.localStorage.setItem('calendarView', v); } catch { /* private mode */ }
  }

  const empty = months.every((m) => m.entries.length === 0);
  const m = months[monthIdx];
  // Flat chronological list (List view): every dated entry across the window.
  // `YYYY-MM-DD` sorts correctly as text, and unlike `new Date(...).getTime()` it cannot be
  // nudged across a boundary by the viewer's timezone.
  const flat = months.flatMap((mb) => mb.entries.filter((e) => !e.pinned)).sort((a, b) => a.date.localeCompare(b.date));
  const recurringPinned = months[0].entries.filter((e) => e.pinned);

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-6 pb-24">
      <div className="mb-5 flex items-end justify-between gap-4 flex-wrap">
        <h1 className="text-2xl md:text-3xl font-bold" style={display}>
          {t('nav.calendar')}
          <span className="ml-3 text-sm font-normal text-[color:var(--color-text-faint)]" style={mono}>{t('cal.next3')}</span>
        </h1>
        <span className="text-xs text-[color:var(--color-text-dim)]" style={mono}>
          {t('cal.dueThisMonth')} <span className="text-[color:var(--color-gold)] font-bold">{fmt(dueThisMonth)}</span>
        </span>
      </div>

      {/* View toggle */}
      <div className="flex items-center gap-1.5 mb-5">
        {VIEWS.map((v) => (
          <button
            key={v.id}
            onClick={() => go(v.id)}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
              view === v.id
                ? 'bg-[color:var(--color-accent)] text-black'
                : 'bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)]'
            )}
          >
            {v.icon} {t(`cal.${v.id}` as TKey)}
          </button>
        ))}
      </div>

      {empty ? (
        <div className="rounded-2xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)] p-8 text-center text-sm text-[color:var(--color-text-dim)]">
          {t('cal.empty')}
        </div>
      ) : view === 'month' ? (
        <section>
          <div className="flex items-center justify-between mb-3">
            <button onClick={() => setMonthIdx((i) => Math.max(0, i - 1))} disabled={monthIdx === 0} className="p-1.5 rounded-lg text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] hover:bg-[color:var(--color-surface-2)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
              <ChevronLeft size={18} />
            </button>
            <div className="text-center">
              <h2 className="text-sm font-bold uppercase tracking-[0.1em]" style={mono}>{m.label}</h2>
              <span className="text-[11px] text-[color:var(--color-text-faint)]" style={mono}>
                {m.out > 0 && <>{t('cal.out')} <span className="text-[color:var(--color-red)]">{fmt(m.out)}</span></>}
                {m.inc > 0 && <> · {t('cal.in')} <span className="text-[color:var(--color-accent)]">{fmt(m.inc)}</span></>}
                {m.out === 0 && m.inc === 0 && t('cal.nothingDue')}
              </span>
            </div>
            <button onClick={() => setMonthIdx((i) => Math.min(months.length - 1, i + 1))} disabled={monthIdx >= months.length - 1} className="p-1.5 rounded-lg text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] hover:bg-[color:var(--color-surface-2)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
              <ChevronRight size={18} />
            </button>
          </div>
          <MonthGrid month={m} />
        </section>
      ) : view === 'agenda' ? (
        months.map((mb) => (
          <section key={mb.key} className="mb-6">
            <div className="flex items-baseline justify-between mb-2 pb-1.5 border-b border-[color:var(--color-border)]">
              <h2 className="text-sm font-bold uppercase tracking-[0.1em]" style={mono}>{mb.label}</h2>
              <span className="text-[11px] text-[color:var(--color-text-faint)]" style={mono}>
                {mb.out > 0 && <>{t('cal.out')} <span className="text-[color:var(--color-red)]">{fmt(mb.out)}</span></>}
                {mb.inc > 0 && <> · {t('cal.in')} <span className="text-[color:var(--color-accent)]">{fmt(mb.inc)}</span></>}
              </span>
            </div>
            {mb.entries.length === 0 ? (
              <p className="text-xs text-[color:var(--color-text-faint)] italic py-2">{t('cal.nothingScheduled')}</p>
            ) : (
              <div className="space-y-1.5">
                {mb.entries.map((e, i) => <EntryRow key={i} e={e} />)}
              </div>
            )}
          </section>
        ))
      ) : (
        <section className="space-y-1.5">
          {recurringPinned.map((e, i) => <EntryRow key={`p${i}`} e={e} />)}
          {flat.map((e, i) => <EntryRow key={i} e={e} showMonth />)}
        </section>
      )}
    </main>
  );
}

'use client';
import { useEffect, useState, useTransition } from 'react';
import { Sparkles, Link2, Loader2, ShoppingCart, Package, X } from 'lucide-react';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { PharosMark } from '@/components/PharosMark';
import { previewItemFromUrl, confirmImportItem } from '@/app/items/actions';
import { formatMoney } from '@/lib/fx';
import { useT } from '@/components/LocaleProvider';
import type { ItemView } from '@/lib/itemStatus';

type PreviewData = {
  title: string;
  price: number;
  store: string;
  specs: string;
  category: string;
  /** P9: set only when the page quotes a currency foreign to this deployment. */
  currency: string;
  existing: { id: string; title: string } | null;
};

/** Compact "Add to Pharos" popup — the bookmarklet's landing page. Reuses the exact
 *  same preview→approve pipeline as the Items page URL import (previewItemFromUrl /
 *  confirmImportItem), just in a single-purpose layout sized for a small popup window. */
export function CaptureClient({ initialUrl }: { initialUrl: string }) {
  const t = useT();
  const [url, setUrl] = useState(initialUrl);
  const [pending, startTransition] = useTransition();
  const [saving, startSave] = useTransition();
  const [preview, setPreview] = useState<PreviewData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState<{ title: string; updated: boolean; priceSkippedCurrency?: string } | null>(null);

  function runPreview(u: string) {
    if (!u.trim()) return;
    setError(null);
    setPreview(null);
    setSaved(null);
    startTransition(async () => {
      const r = await previewItemFromUrl(u.trim());
      if (!r.ok) {
        setError(r.error);
        return;
      }
      setPreview({
        title: r.title,
        price: r.price,
        store: r.store,
        specs: r.specs,
        category: r.category,
        currency: r.currency,
        existing: r.existing,
      });
    });
  }

  // Auto-preview once when the bookmarklet handed us a URL.
  useEffect(() => {
    if (initialUrl) runPreview(initialUrl);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialUrl]);

  function save(view: ItemView) {
    if (!preview) return;
    setError(null);
    startSave(async () => {
      const r = await confirmImportItem(
        {
          url: url.trim(),
          title: preview.title,
          price: preview.price,
          store: preview.store,
          specs: preview.specs,
          category: preview.category,
          currency: preview.currency,
        },
        view
      );
      if (!r.ok) {
        setError(r.error);
        return;
      }
      setSaved({ title: r.title, updated: r.updated, priceSkippedCurrency: r.priceSkippedCurrency });
      setPreview(null);
    });
  }

  return (
    <main className="min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-sm rounded-2xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)] p-5">
        <div className="flex items-center gap-2 mb-4">
          <PharosMark size={22} pulse={false} className="text-[color:var(--color-accent)]" />
          <span className="font-semibold text-sm" style={{ fontFamily: 'var(--font-display)' }}>{t('cap.title')}</span>
        </div>

        {saved ? (
          <div className="text-center py-4">
            <p className="text-sm text-[color:var(--color-accent)] mb-1">{saved.updated ? t('cap.updatedExisting', { title: saved.title }) : t('cap.added', { title: saved.title })}</p>
            {saved.priceSkippedCurrency && (
              <p className="text-[11px] text-[color:var(--color-gold)] mb-1">{t('cap.priceSkippedCurrency', { code: saved.priceSkippedCurrency })}</p>
            )}
            <p className="text-xs text-[color:var(--color-text-faint)] mb-4">{t('cap.closeHint')}</p>
            <Button variant="ghost" onClick={() => window.close()} className="mx-auto">
              <X size={14} /> {t('cap.close')}
            </Button>
          </div>
        ) : (
          <>
            <div className="flex gap-2">
              <Input
                icon={<Link2 size={14} />}
                value={url}
                onChange={(e) => {
                  setUrl(e.target.value);
                  setPreview(null);
                  setError(null);
                }}
                placeholder={t('cap.urlPlaceholder')}
                onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), runPreview(url))}
                disabled={pending || saving}
              />
              <Button variant="primary" onClick={() => runPreview(url)} disabled={pending || saving || !url.trim()} className="shrink-0">
                {pending ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
              </Button>
            </div>

            {pending && <p className="text-[11px] text-[color:var(--color-cyan)] mt-2">{t('cap.fetching')}</p>}
            {error && <p className="text-[11px] text-[color:var(--color-red)] mt-2">{error}</p>}

            {preview && (
              <div className="mt-3 rounded-xl border border-[color:var(--color-accent)] bg-[color:var(--color-surface-2)] p-3">
                {preview.existing && (
                  <p className="text-[10px] text-[color:var(--color-gold)] mb-2">{t('cap.matchesExisting', { title: preview.existing.title })}</p>
                )}
                <p className="font-semibold text-sm leading-snug" style={{ fontFamily: 'var(--font-display)' }}>{preview.title}</p>
                <p className="text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-wider mt-0.5">
                  {preview.category} · {preview.store}
                </p>
                {preview.price > 0 && (
                  <p className="text-sm font-semibold text-[color:var(--color-accent)] mt-1.5">
                    {/* P9: a foreign page shows its own symbol, so the figure is not read as base. */}
                    {preview.currency ? formatMoney(preview.price, preview.currency) : preview.price.toFixed(2)}
                  </p>
                )}
                <div className="flex gap-2 mt-3">
                  <Button variant="primary" onClick={() => save('shopping')} disabled={saving} className="flex-1 justify-center">
                    {saving ? <Loader2 size={13} className="animate-spin" /> : <ShoppingCart size={13} />} {t('cap.addShopping')}
                  </Button>
                  <Button variant="ghost" onClick={() => save('inventory')} disabled={saving} className="flex-1 justify-center">
                    {saving ? <Loader2 size={13} className="animate-spin" /> : <Package size={13} />} {t('cap.addInventory')}
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </main>
  );
}

'use client';
import { useState, useMemo, useTransition } from 'react';
import { Plus, Trash2, Check, Archive, ArchiveRestore, Pencil, X, FileCheck2, IdCard } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { DateInput } from '@/components/ui/DateInput';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { useConfirm } from '@/components/ui/ConfirmDialog';
import { cn } from '@/components/ui/cn';
import { documentDaysUntilExpiry, documentStatus, type DocStatus } from '@/lib/documentExpiry';
import type { SerializedDocument } from '@/types';
import { createDocument, updateDocument, deleteDocument, setDocumentArchived } from './actions';
import { formatDate, formatTime, formatDateTime } from '@/lib/i18n/format';
import { useLocale } from '@/components/LocaleProvider';

// P42 — personal document expiry tracker. Inline English wording (like BillsClient), which
// is not yet run through i18n; only the nav label is translated.

const inputClass =
  'w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[color:var(--color-accent)]';

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="block">
      <span className="block text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-[0.12em] mb-1" style={{ fontFamily: 'var(--font-mono)' }}>
        {label}
      </span>
      {children}
    </label>
  );
}

const STATUS_STYLE: Record<DocStatus, { label: (d: number) => string; color: string }> = {
  expired: { label: (d) => `expired ${-d}d ago`, color: 'var(--color-red)' },
  soon: { label: (d) => (d === 0 ? 'expires today' : `in ${d}d`), color: 'var(--color-gold)' },
  ok: { label: (d) => `in ${d}d`, color: 'var(--color-text-faint)' },
};

const fmtDate = (s: string | null, locale: string) => formatDate(s, locale, { day: '2-digit', month: 'short', year: 'numeric' }, '—');

const toInputDate = (s: string | null) => {
  if (!s) return '';
  const d = new Date(s);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
};

type Draft = Partial<SerializedDocument> | null;

export function DocumentsClient({ documents, leadDays }: { documents: SerializedDocument[]; leadDays: number }) {
  const locale = useLocale();
  const confirm = useConfirm();
  const [pending, startTransition] = useTransition();
  const [showArchived, setShowArchived] = useState(false);
  const [editing, setEditing] = useState<Draft>(null); // {} = new, {…} = edit, null = closed
  const [error, setError] = useState('');

  const visible = useMemo(
    () => documents.filter((d) => showArchived || !d.archived),
    [documents, showArchived]
  );
  const archivedCount = documents.filter((d) => d.archived).length;

  function openNew() {
    setError('');
    setEditing({});
  }
  function openEdit(d: SerializedDocument) {
    setError('');
    setEditing(d);
  }

  function submit(fd: FormData) {
    setError('');
    startTransition(async () => {
      const id = editing && editing._id;
      const r = id ? await updateDocument(id, fd) : await createDocument(fd);
      if (r.ok) setEditing(null);
      else setError(r.error || 'Could not save');
    });
  }

  function remove(d: SerializedDocument) {
    startTransition(async () => {
      const ok = await confirm({
        title: 'Delete document',
        message: `Delete “${d.title}”? It moves to Trash (restorable for 30 days).`,
        confirmLabel: 'Delete',
        danger: true,
      });
      if (ok) await deleteDocument(d._id);
    });
  }

  return (
    <main className="max-w-[1100px] mx-auto px-4 py-6 pb-24">
      <div className="mb-6 pb-4 border-b border-[color:var(--color-border)] flex items-end justify-between gap-4 flex-wrap">
        <div className="flex items-baseline gap-3 flex-wrap">
          <h1 className="text-2xl md:text-3xl font-bold flex items-center gap-2" style={{ fontFamily: 'var(--font-display)' }}>
            <IdCard size={26} className="text-[color:var(--color-accent)]" /> Documents
          </h1>
          <span className="text-sm text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
            {visible.length} shown
          </span>
        </div>
        <div className="flex items-center gap-2">
          {archivedCount > 0 && (
            <button
              onClick={() => setShowArchived((v) => !v)}
              className="text-xs text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] px-2"
              style={{ fontFamily: 'var(--font-mono)' }}
            >
              {showArchived ? 'hide archived' : `show archived (${archivedCount})`}
            </button>
          )}
          <Button variant="primary" onClick={openNew}>
            <Plus size={16} strokeWidth={2.5} /> New document
          </Button>
        </div>
      </div>

      <p className="text-xs text-[color:var(--color-text-dim)] -mt-3 mb-5">
        Passports, IDs, driving licences, residence permits, vehicle registration/MOT — anything with a renewal deadline.
        You get an alert when one is within {leadDays} days of expiring (Settings → Notifications).
      </p>

      {visible.length === 0 ? (
        <div className="py-20 text-center text-[color:var(--color-text-faint)]">
          <FileCheck2 size={40} className="mx-auto mb-3 opacity-40" />
          <p className="text-sm">No documents yet. Add your passport, ID, or licence to track its expiry.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {visible.map((d) => {
            const days = documentDaysUntilExpiry(d.expiryDate);
            const status = documentStatus(days, leadDays);
            const s = STATUS_STYLE[status];
            return (
              <div
                key={d._id}
                className={cn(
                  'flex items-center gap-3 rounded-xl border p-3 transition-colors',
                  d.archived ? 'border-[color:var(--color-border)] opacity-60' : 'border-[color:var(--color-border)] hover:border-[color:var(--color-border-light)]'
                )}
              >
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-semibold text-sm truncate" style={{ fontFamily: 'var(--font-display)' }}>{d.title}</span>
                    {d.type && <span className="text-[10px] uppercase tracking-wider text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>{d.type}</span>}
                    {d.holder && <span className="text-[10px] text-[color:var(--color-text-dim)]">· {d.holder}</span>}
                  </div>
                  <div className="flex items-center gap-2 flex-wrap text-[11px] text-[color:var(--color-text-faint)] mt-0.5" style={{ fontFamily: 'var(--font-mono)' }}>
                    <span>exp {fmtDate(d.expiryDate, locale)}</span>
                    {days !== null && <span style={{ color: s.color }}>· {s.label(days)}</span>}
                    {d.number && <span className="truncate">· #{d.number}</span>}
                  </div>
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  <button onClick={() => openEdit(d)} title="Edit" className="p-1.5 rounded-lg text-[color:var(--color-text-faint)] hover:text-[color:var(--color-accent)]"><Pencil size={14} /></button>
                  <button
                    onClick={() => startTransition(async () => { await setDocumentArchived(d._id, !d.archived); })}
                    title={d.archived ? 'Unarchive' : 'Archive'}
                    className="p-1.5 rounded-lg text-[color:var(--color-text-faint)] hover:text-[color:var(--color-text)]"
                  >
                    {d.archived ? <ArchiveRestore size={14} /> : <Archive size={14} />}
                  </button>
                  <button onClick={() => remove(d)} title="Delete" className="p-1.5 rounded-lg text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)]"><Trash2 size={14} /></button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <Modal open={editing !== null} onClose={() => setEditing(null)} title={editing && editing._id ? 'Edit document' : 'New document'} size="md">
        <form
          action={submit}
          className="space-y-3"
        >
          <Field label="Title *">
            <Input name="title" defaultValue={editing?.title || ''} placeholder="Passport" required />
          </Field>
          <div className="grid sm:grid-cols-2 gap-3">
            <Field label="Type">
              <Input name="type" defaultValue={editing?.type || ''} placeholder="passport / id / licence" />
            </Field>
            <Field label="Holder">
              <Input name="holder" defaultValue={editing?.holder || ''} placeholder="who it belongs to" />
            </Field>
            <Field label="Document number">
              <Input name="number" defaultValue={editing?.number || ''} />
            </Field>
            <Field label="Issued (optional)">
              <DateInput name="issuedAt" value={toInputDate(editing?.issuedAt ?? null)} onValueChange={(v) => setEditing(prev => ({ ...(prev || {}), issuedAt: v }))} className={inputClass} />
            </Field>
            <Field label="Expires *">
              <DateInput name="expiryDate" required value={toInputDate(editing?.expiryDate ?? null)} onValueChange={(v) => setEditing(prev => ({ ...(prev || {}), expiryDate: v }))} className={inputClass} />
            </Field>
          </div>
          <Field label="Notes">
            <textarea name="notes" defaultValue={editing?.notes || ''} rows={2} className={inputClass} />
          </Field>
          {error && <p className="text-xs text-[color:var(--color-red)]" style={{ fontFamily: 'var(--font-mono)' }}>{error}</p>}
          <div className="flex justify-end gap-2 pt-1">
            <Button type="button" variant="ghost" onClick={() => setEditing(null)}><X size={14} /> Cancel</Button>
            <Button type="submit" variant="primary" disabled={pending}>
              <Check size={14} /> {editing && editing._id ? 'Save' : 'Add'}
            </Button>
          </div>
        </form>
      </Modal>
    </main>
  );
}

'use client';
import { useEffect } from 'react';
import { RotateCw, RefreshCw } from 'lucide-react';
import { reportClientError } from '@/lib/clientErrorReporting';

// Root error boundary — catches render/data errors AND uncaught Server Action
// failures in any route segment.
export default function Error({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  // A redeploy (or a Docker rebuild while a tab stayed open) leaves the browser with
  // a stale JS bundle whose Server Action IDs no longer exist on the server. The only
  // real recovery is a FULL reload to fetch the new bundle — `reset()` re-renders the
  // same stale code and won't help. Detect that class of error and lead with Reload.
  const msg = error?.message || '';
  const isStaleDeploy =
    /server action|failed to find|connection closed|loading chunk|chunkloaderror|fetch failed|failed to fetch|unexpected response|deployment/i.test(
      msg
    );

  useEffect(() => {
    console.error('[route error]', error);
    // Only DEPLOYMENT-SPECIFIC signatures (a missing Server Action id, a chunk that no longer
    // exists) are skipped: they follow every release and self-heal by reloading. The broader
    // isStaleDeploy phrases ("failed to fetch", "connection closed"…) also describe real network
    // and backend failures, so those ARE reported, tagged so they can be filtered in Sentry.
    if (!/failed to find server action|loading chunk \d+ failed|chunkloaderror/i.test(msg)) {
      reportClientError(error, isStaleDeploy ? { maybe_stale_deploy: 'true' } : undefined);
    }
    // Auto-recover stale-deploy errors: silently reload to fetch the new bundle so the
    // user never sees an "application error". Guard against a reload loop with a
    // short-lived flag (if the error recurs within 15s we stop and show the button).
    if (isStaleDeploy && typeof window !== 'undefined') {
      try {
        const last = Number(sessionStorage.getItem('stale-reload-at') || 0);
        if (Date.now() - last > 15000) {
          sessionStorage.setItem('stale-reload-at', String(Date.now()));
          window.location.reload();
        }
      } catch {
        /* sessionStorage blocked — fall through to the manual button */
      }
    }
  }, [error, isStaleDeploy]);

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-24 text-center">
      <p className="text-5xl mb-4">{isStaleDeploy ? '🔄' : '⚠️'}</p>
      <h1 className="text-xl font-bold mb-2" style={{ fontFamily: 'var(--font-display)' }}>
        {isStaleDeploy ? 'The app was updated' : 'Something went wrong'}
      </h1>
      <p className="text-sm text-[color:var(--color-text-dim)] max-w-md mx-auto mb-6 break-words">
        {isStaleDeploy
          ? 'This tab was loaded before the latest update. Reload to get the new version and continue.'
          : msg || 'Unexpected error while loading this page.'}
        {!isStaleDeploy && error.digest && (
          <span className="block mt-1 text-[10px] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
            ref: {error.digest}
          </span>
        )}
      </p>
      <div className="flex items-center justify-center gap-3">
        <button
          onClick={() => window.location.reload()}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-[color:var(--color-accent)] text-black text-sm font-semibold hover:opacity-90 transition-opacity"
        >
          <RefreshCw size={15} /> Reload page
        </button>
        {!isStaleDeploy && (
          <button
            onClick={reset}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg border border-[color:var(--color-border)] text-[color:var(--color-text-dim)] text-sm font-semibold hover:text-[color:var(--color-text)] transition-colors"
          >
            <RotateCw size={15} /> Try again
          </button>
        )}
      </div>
    </main>
  );
}

