'use client';
import { cur } from '@/lib/money';
import { useEffect, useState, useTransition } from 'react';
import { Loader2, Copy, Check, Merge } from 'lucide-react';
import { Modal } from '@/components/ui/Modal';
import { Button } from '@/components/ui/Button';
import { cn } from '@/components/ui/cn';
import { useRouter } from 'next/navigation';
import { findDuplicateItems, mergeItems, type DupItem, type ItemDupGroup } from './actions';

function fileUrl(p: string) {
  return `/api/files/${p.split('/').map(encodeURIComponent).join('/')}`;
}

/**
 * Keep-radio list over a set of duplicate items — pick the one to KEEP; the rest
 * merge into it. Reused by the auto-group modal AND the select-mode manual merge.
 */
export function MergeItemsPicker({
  items,
  keepId,
  onKeep,
}: {
  items: DupItem[];
  keepId: string;
  onKeep: (id: string) => void;
}) {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
      {items.map((it) => {
        const isKeep = keepId === it._id;
        return (
          <button
            key={it._id}
            type="button"
            onClick={() => onKeep(it._id)}
            className={cn(
              'flex items-center gap-2.5 text-left rounded-lg border p-2 transition-colors min-w-0',
              isKeep
                ? 'border-[color:var(--color-accent)] bg-[color:var(--color-surface-2)]'
                : 'border-[color:var(--color-border)] hover:border-[color:var(--color-border-light)] opacity-80'
            )}
          >
            <span
              className={cn(
                'shrink-0 w-4 h-4 rounded-full border flex items-center justify-center',
                isKeep ? 'border-[color:var(--color-accent)] bg-[color:var(--color-accent)]' : 'border-[color:var(--color-border-light)]'
              )}
            >
              {isKeep && <Check size={11} strokeWidth={3} className="text-black" />}
            </span>
            {it.thumbPath ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={fileUrl(it.thumbPath)} alt="" className="w-9 h-9 rounded object-cover bg-[color:var(--color-surface-3)] shrink-0" />
            ) : (
              <span className="w-9 h-9 rounded bg-[color:var(--color-surface-3)] grid place-items-center text-[9px] text-[color:var(--color-text-faint)] shrink-0 uppercase">
                {it.status.slice(0, 3)}
              </span>
            )}
            <span className="min-w-0 flex-1">
              <span className="flex items-center gap-1.5 text-[11px]">
                <span className="text-[color:var(--color-text-dim)] capitalize">{it.status}</span>
                {it.currentPrice > 0 && (
                  <span className="text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
                    {cur()}
                    {it.currentPrice}
                  </span>
                )}
                {isKeep && <span className="text-[9px] uppercase tracking-wider text-[color:var(--color-accent)]">keep</span>}
              </span>
              <span className="block text-xs text-[color:var(--color-text)] truncate">{it.title}</span>
              <span className="block text-[10px] text-[color:var(--color-text-faint)] truncate" style={{ fontFamily: 'var(--font-mono)' }}>
                {it.links} links · {it.photos} photos · {it.receipts} receipts
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );
}

/** "Find duplicate products" — auto-grouped by title; pick the keeper, merge the rest. */
export function ItemDuplicatesModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [groups, setGroups] = useState<ItemDupGroup[]>([]);
  const [keepBy, setKeepBy] = useState<Record<string, string>>({});
  const [done, setDone] = useState<Record<string, number>>({});
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    setDone({});
    findDuplicateItems()
      .then((g) => {
        setGroups(g);
        setKeepBy(Object.fromEntries(g.map((grp) => [grp.key, grp.items[0]?._id])));
      })
      .finally(() => setLoading(false));
  }, [open]);

  function handleMerge(grp: ItemDupGroup) {
    const keep = keepBy[grp.key];
    if (!keep) return;
    const drops = grp.items.map((r) => r._id).filter((id) => id !== keep);
    if (drops.length === 0) return;
    setBusyKey(grp.key);
    startTransition(async () => {
      const r = await mergeItems(keep, drops);
      setBusyKey(null);
      if (r.ok) {
        setDone((d) => ({ ...d, [grp.key]: r.merged }));
        router.refresh();
      }
    });
  }

  const pending = groups.filter((g) => !done[g.key]);
  const totalDupes = groups.reduce((s, g) => s + (g.items.length - 1), 0);

  return (
    <Modal open={open} onClose={onClose} title="Find duplicate products" size="xl">
      {loading ? (
        <div className="py-16 flex flex-col items-center gap-3 text-[color:var(--color-text-dim)]">
          <Loader2 size={26} className="animate-spin" />
          <p className="text-sm">Scanning for duplicates…</p>
        </div>
      ) : groups.length === 0 ? (
        <div className="py-16 text-center text-[color:var(--color-text-faint)]">
          <p className="text-5xl mb-3">✨</p>
          <p className="text-sm">No duplicate products found. Clean library!</p>
        </div>
      ) : (
        <div className="space-y-4">
          <p className="text-xs text-[color:var(--color-text-dim)]" style={{ fontFamily: 'var(--font-mono)' }}>
            <Copy size={12} className="inline mr-1" />
            {groups.length} group{groups.length === 1 ? '' : 's'} · {totalDupes} duplicate{totalDupes === 1 ? '' : 's'} to merge. Pick the one to{' '}
            <b>keep</b> in each (defaults to the most complete); the rest merge into it.
          </p>

          {groups.map((grp) => {
            const merged = done[grp.key];
            const keep = keepBy[grp.key];
            return (
              <div
                key={grp.key}
                className={cn(
                  'border rounded-xl p-3 transition-colors',
                  merged ? 'border-[color:var(--color-accent)] bg-[#00ff8808]' : 'border-[color:var(--color-border)]'
                )}
              >
                <div className="flex items-center justify-between gap-2 mb-2">
                  <span className="text-xs font-semibold truncate min-w-0" style={{ fontFamily: 'var(--font-mono)' }}>
                    {grp.items[0].title}
                  </span>
                  {merged ? (
                    <span className="text-[11px] text-[color:var(--color-accent)] flex items-center gap-1 shrink-0" style={{ fontFamily: 'var(--font-mono)' }}>
                      <Check size={13} /> merged {merged}
                    </span>
                  ) : (
                    <Button variant="primary" size="sm" onClick={() => handleMerge(grp)} disabled={busyKey === grp.key}>
                      {busyKey === grp.key ? <Loader2 size={13} className="animate-spin" /> : <Merge size={13} />}
                      Merge {grp.items.length} → 1
                    </Button>
                  )}
                </div>

                {!merged && (
                  <MergeItemsPicker items={grp.items} keepId={keep} onKeep={(id) => setKeepBy((k) => ({ ...k, [grp.key]: id }))} />
                )}
              </div>
            );
          })}

          {pending.length === 0 && (
            <div className="text-center pt-2">
              <Button variant="ghost" onClick={onClose}>
                Done
              </Button>
            </div>
          )}
        </div>
      )}
    </Modal>
  );
}

'use client';
import { useState, useRef, useTransition } from 'react';
import { useT } from '@/components/LocaleProvider';
import { ImagePlus, Trash2, Star, Loader2, ChevronLeft, ChevronRight, Sparkles } from 'lucide-react';
import { shrinkImage } from '@/lib/clientImage';
import { useConfirm } from '@/components/ui/ConfirmDialog';
import { uploadItemPhotos, deleteItemPhoto, setItemCover, fetchItemPhotos } from './actions';

function fileUrl(p: string) {
  return `/api/files/${p.split('/').map(encodeURIComponent).join('/')}`;
}

/** Product photo gallery: hero + thumbnails, with upload / delete / set-cover / AI fetch. */
export function ItemPhotoGallery({
  itemId,
  photos: initialPhotos,
  canFetch,
  onChange,
}: {
  itemId: string;
  photos: string[];
  canFetch: boolean;
  /** Reports every upload/delete/fetch/cover change to the parent, so a remount re-seeds from the new list (#245). */
  onChange?: (photos: string[]) => void;
}) {
  const [photos, setLocal] = useState<string[]>(initialPhotos);
  function setPhotos(next: string[]) {
    setLocal(next);
    onChange?.(next);
  }
  const [active, setActive] = useState(0);
  const t = useT();
  const [pending, startTransition] = useTransition();
  const [uploading, setUploading] = useState(false);
  const [fetching, setFetching] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const confirm = useConfirm();

  const hero = photos[active] ?? photos[0];

  function handleFetch() {
    setMsg(null);
    setFetching(true);
    startTransition(async () => {
      const r = await fetchItemPhotos(itemId);
      setFetching(false);
      setPhotos(r.photos);
      setMsg(r.ok ? `✓ Fetched ${r.added} image${r.added === 1 ? '' : 's'}` : (r.error ?? 'Failed'));
    });
  }

  const fetchBtn = canFetch && (
    <button
      type="button"
      onClick={handleFetch}
      disabled={fetching || uploading}
      title={t('it.searchPhotos')}
      className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] text-[color:var(--color-cyan)] hover:border-[color:var(--color-cyan)] transition-colors disabled:opacity-50"
    >
      {fetching ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
      {fetching ? 'Fetching…' : 'Fetch photos'}
    </button>
  );

  async function handleFiles(files: FileList | null) {
    if (!files || files.length === 0) return;
    setUploading(true);
    const fd = new FormData();
    for (const f of Array.from(files)) {
      try {
        fd.append('files', await shrinkImage(f, 1600));
      } catch {
        fd.append('files', f);
      }
    }
    const r = await uploadItemPhotos(itemId, fd);
    if (r.photos.length) setPhotos(r.photos);
    setUploading(false);
    if (inputRef.current) inputRef.current.value = '';
  }

  async function handleDelete(p: string) {
    const ok = await confirm({ title: 'Delete photo', message: 'Remove this photo?', confirmLabel: 'Delete', danger: true });
    if (ok)
      startTransition(async () => {
        const r = await deleteItemPhoto(itemId, p);
        setPhotos(r.photos);
        // Move the selection only once the delete has actually happened, and only as far as it
        // has to. Resetting to 0 up front meant a failed delete still threw you back to the
        // first photo, with the list unchanged — so the gallery said something had happened
        // when nothing had. Clamping keeps you where you were when a middle photo goes.
        setActive((i) => Math.min(i, Math.max(0, r.photos.length - 1)));
      });
  }

  const uploadBtn = (
    <>
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        multiple
        capture="environment"
        className="hidden"
        onChange={(e) => handleFiles(e.target.files)}
      />
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        disabled={uploading}
        className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] hover:border-[color:var(--color-accent)] transition-colors"
      >
        {uploading ? <Loader2 size={13} className="animate-spin" /> : <ImagePlus size={13} />}
        {uploading ? 'Uploading…' : 'Add photos'}
      </button>
    </>
  );

  // Empty state
  if (photos.length === 0) {
    return (
      <div className="space-y-2">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          disabled={uploading || fetching}
          className="aspect-[4/3] w-full rounded-2xl border-2 border-dashed border-[color:var(--color-border)] hover:border-[color:var(--color-accent)] bg-[color:var(--color-surface)] flex flex-col items-center justify-center gap-2 text-[color:var(--color-text-faint)] transition-colors"
        >
          <input ref={inputRef} type="file" accept="image/*" multiple capture="environment" className="hidden" onChange={(e) => handleFiles(e.target.files)} />
          {uploading ? <Loader2 size={28} className="animate-spin" /> : <ImagePlus size={28} />}
          <span className="text-xs">{uploading ? 'Uploading…' : 'Add product photos'}</span>
        </button>
        <div className="flex items-center gap-2 flex-wrap">
          {fetchBtn}
          {msg && <span className="text-[10px] text-[color:var(--color-text-dim)]" style={{ fontFamily: 'var(--font-mono)' }}>{msg}</span>}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {/* Hero */}
      <div className="relative aspect-[4/3] w-full rounded-2xl overflow-hidden bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] group">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <a href={fileUrl(hero)} target="_blank" rel="noopener noreferrer" className="block w-full h-full">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={fileUrl(hero)} alt="Product" className="w-full h-full object-contain" />
        </a>

        {photos.length > 1 && (
          <>
            <button type="button" onClick={() => setActive((a) => (a - 1 + photos.length) % photos.length)} className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 transition-opacity">
              <ChevronLeft size={16} />
            </button>
            <button type="button" onClick={() => setActive((a) => (a + 1) % photos.length)} className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 transition-opacity">
              <ChevronRight size={16} />
            </button>
            <span className="absolute bottom-2 right-2 text-[10px] px-1.5 py-0.5 rounded bg-black/60 text-white" style={{ fontFamily: 'var(--font-mono)' }}>
              {active + 1}/{photos.length}
            </span>
          </>
        )}

        {/* Per-photo actions */}
        <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 transition-opacity">
          {active !== 0 && (
            <button type="button" title={t('it.setCover')} onClick={() => startTransition(async () => { const r = await setItemCover(itemId, hero); setPhotos(r.photos); setActive(0); })} disabled={pending} className="w-7 h-7 rounded-full bg-black/55 text-white flex items-center justify-center hover:bg-black/75">
              <Star size={13} />
            </button>
          )}
          <button type="button" title={t('it.deletePhoto')} onClick={() => handleDelete(hero)} disabled={pending} className="w-7 h-7 rounded-full bg-black/55 text-white flex items-center justify-center hover:bg-[color:var(--color-red)]">
            <Trash2 size={13} />
          </button>
        </div>
      </div>

      {/* Thumbnails + upload */}
      <div className="flex items-center gap-2 flex-wrap">
        {photos.map((p, i) => (
          <button
            key={p}
            type="button"
            onClick={() => setActive(i)}
            className={`w-12 h-12 rounded-lg overflow-hidden border-2 transition-all ${i === active ? 'border-[color:var(--color-accent)]' : 'border-[color:var(--color-border)] opacity-70 hover:opacity-100'}`}
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={fileUrl(p)} alt="" className="w-full h-full object-cover" />
          </button>
        ))}
        {uploadBtn}
        {fetchBtn}
      </div>
      {msg && <p className="text-[10px] text-[color:var(--color-text-dim)]" style={{ fontFamily: 'var(--font-mono)' }}>{msg}</p>}
    </div>
  );
}

