                {test2 && (
                  <span
                    className={cn('text-[11px]', test2.startsWith('Connection OK') ? 'text-[color:var(--color-accent)]' : test2 === 'testing…' ? 'text-[color:var(--color-text-dim)]' : 'text-[color:var(--color-red)]')}
