          placeholder="Bot token (123456:ABC-…)"
          className={inputClass}
          style={{ fontFamily: 'var(--font-mono)' }}
        />
      )}
      {meta.needs.includes('target') && (
        <input
          value={ch.target || ''}
          onChange={(e) => set({ target: e.target.value })}
          placeholder="Chat id (e.g. 123456789)"
          className={inputClass}
          style={{ fontFamily: 'var(--font-mono)' }}
