function chainData(data: unknown[]) {
  const obj: { select: () => typeof obj; sort: () => typeof obj; lean: () => Promise<unknown[]> } = {
    select: () => obj,
    sort: () => obj,
    lean: async () => data,
  };
  return obj;
}

