/** Save manual asset accounts for net worth (account name → balance). Zero/empty
 *  balances are dropped — an account with no balance contributes nothing (PA2). */
export async function saveAssetAccounts(accounts: Record<string, number>): Promise<{ ok: boolean }> {
  await assertCanWrite();
  await connectDB();
  const clean: Record<string, number> = {};
  for (const [k, v] of Object.entries(accounts || {})) {
    const n = Number(v);
    // `>= 0`, not `> 0`: a zero balance is a real state (an emptied cash envelope, a closed-out
    // account kept for the record), and dropping it here deleted the account behind the user's
    // back — the same bug the editor had on the client side. Removal is the X button, and it
    // sends the account absent from the map, which this loop still honours.
    if (k.trim() && Number.isFinite(n) && n >= 0) clean[k.trim().slice(0, 60)] = Math.round(n * 100) / 100;
  }
  await (await scoped(AppConfig)).updateOne({ key: 'singleton' }, { $set: { assetAccounts: clean } }, { upsert: true });
  await invalidateAppSettingsForRequest();
  revalidatePath('/reports');
  revalidatePath('/settings');
  return { ok: true };
}

/** Save the asset depreciation model (P29): master toggle, salvage floor %, a
 *  default annual rate, and per item-category annual rates. Percent values are
 *  clamped to 0..100. Categories the user left empty are simply not sent (the
 *  built-in per-category default applies at read time). Affects the depreciated
 *  owned-inventory value on Reports. */
export async function saveDepreciation(cfg: {
  enabled: boolean;
  floorPct: number;
  defaultRate: number;
  rates: Record<string, number>;
}): Promise<{ ok: boolean }> {
  await assertCanWrite();
  await connectDB();
  const clampPct = (n: unknown) => Math.min(100, Math.max(0, Number(n) || 0));
  const rates: Record<string, number> = {};
  for (const [k, v] of Object.entries(cfg?.rates || {})) {
    const key = k.trim();
    const n = Number(v);
    if (key && Number.isFinite(n) && n >= 0) rates[key.slice(0, 60)] = Math.min(100, n);
  }
  const clean = {
    enabled: cfg?.enabled !== false,
    floorPct: clampPct(cfg?.floorPct),
    defaultRate: clampPct(cfg?.defaultRate),
    rates,
  };
  await (await scoped(AppConfig)).updateOne({ key: 'singleton' }, { $set: { depreciation: clean } }, { upsert: true });
  await invalidateAppSettingsForRequest();
  revalidatePath('/reports');
  revalidatePath('/settings');
  return { ok: true };
}

/** A stored file reference is safe only if it's a contained relative path. A
 *  tampered backup must not be able to point filePath/thumbPath/photos at e.g.
 *  ../../etc/passwd, which would then be served or unlinked by purge. */
function isSafeStoredPath(p: unknown): boolean {
  if (typeof p !== 'string' || !p || p.includes('\0')) return false;
  if (p.startsWith('/') || /^[a-zA-Z]:/.test(p)) return false; // absolute
  return !p.split(/[/\\]/).some((seg) => seg === '..'); // no traversal
}

/** Restore from a backup JSON — upserts each document by _id (merges, never duplicates). */
export async function importData(json: string): Promise<{ ok: boolean; restored: number; error?: string; warnings?: string[] }> {
  await requireAdmin();
  // Pre-flight the same check the Verify button runs. Errors mean the file is not a
  // usable backup at all (empty, truncated, no envelope, zero documents) — cases that
  // used to either throw a vague message or, worse, report a successful restore of
  // nothing. Warnings do NOT block: a backup missing one collection is still worth
  // restoring, but the user is told what got skipped instead of it happening silently.
  const check = verifyBackupJson(json, BACKUP_KEYS);
  if (!check.ok) {
    return { ok: false, restored: 0, error: check.issues.filter((i) => i.level === 'error').map((i) => i.message).join(' ') };
  }
  const warnings = check.issues.filter((i) => i.level === 'warning').map((i) => i.message);
  const data = JSON.parse(json) as { collections?: Record<string, unknown[]> };
  const cols = data.collections as Record<string, unknown[]>;

  await connectDB();
  let restored = 0;
  for (const [key, Model] of Object.entries(BACKUP_MODELS)) {
    const docs = cols[key];
    if (!Array.isArray(docs)) continue;
    // The mirror of the export bug (#195), and the destructive half: restoring through the
    // raw import upserted the tenant's own backup into the DEFAULT database, so their data
    // never reappeared in their workspace and the base DB was polluted with it. Resolved
    // once per collection rather than per document — the lookup is memoised per request,
    // but a backup can carry tens of thousands of documents.
    const ScopedModel = await scoped(Model as typeof Item);
    for (const raw of docs) {
      if (!raw || typeof raw !== 'object') continue;
      const { _id, __v, createdAt, updatedAt, ...rest } = raw as Record<string, unknown>;
      void __v;
      void createdAt;
      void updatedAt;
      // Drop tampered file references so a malicious backup can't aim purge/serve
      // at arbitrary files (defense in depth on top of storage.ts containment).
      for (const k of ['filePath', 'thumbPath'] as const) {
        if (k in rest && !isSafeStoredPath(rest[k])) delete rest[k];
      }
      if (Array.isArray(rest.photos)) rest.photos = rest.photos.filter(isSafeStoredPath);
      if (Array.isArray(rest.attachments)) {
        rest.attachments = (rest.attachments as unknown[]).filter(
          (a) => a && typeof a === 'object' && isSafeStoredPath((a as Record<string, unknown>).path)
        );
      }
      // `exportData` only dumps live documents, so anything in a backup was NOT in the Trash when
      // it was written. If the copy in the database has been trashed since, `$set` alone cannot
      // undo that: a document from before the soft-delete plugin carries no `deletedAt` key for it
      // to overwrite, and the restore would leave the item invisible, in a Trash it was never in.
      const update: Record<string, unknown> = { $set: rest };
      if (!('deletedAt' in rest)) update.$unset = { deletedAt: '' };
      try {
        if (_id) await ScopedModel.updateOne({ _id }, update, { upsert: true }).setOptions({ withDeleted: true });
        else await ScopedModel.create(rest);
        restored++;
      } catch {
        /* skip a doc that won't validate */
      }
    }
  }
  invalidateStoreCache();
  revalidatePath('/settings');
  revalidatePath('/');
  return { ok: true, restored, ...(warnings.length > 0 ? { warnings } : {}) };
}

// ─── Encrypted backup (P54) ──────────────────────────────────────────────────
// The plain export above writes full financial data as plaintext; copied to a USB stick,
// a shared NAS folder, or a cloud drive it has no protection. These two wrap the SAME
// backup JSON in a passphrase-encrypted envelope (AES-256-GCM + scrypt, lib/backupCrypto).
// Opt-in — the plaintext path is untouched, so existing backup.sh flows keep working. The
// passphrase is only ever in memory (a server-action argument), never stored.

/** Encrypted variant of exportData: the same backup JSON, wrapped under a passphrase. */
export async function exportDataEncrypted(passphrase: string): Promise<string> {
  const json = await exportData(); // requireAdmin + build (unchanged)
  return encryptBackup(json, passphrase);
}

/** Restore from an encrypted backup: decrypt with the passphrase, then the normal import.
 *  A wrong passphrase fails clearly here rather than looking like a corrupt restore. */
export async function importDataEncrypted(
  envelope: string,
  passphrase: string
): Promise<{ ok: boolean; restored: number; error?: string; warnings?: string[] }> {
  await requireAdmin();
  let json: string;
  try {
    json = decryptBackup(envelope, passphrase);
  } catch (e) {
    return { ok: false, restored: 0, error: (e as Error).message };
  }
  return importData(json);
}

// ─── Trash (soft-deleted records) ────────────────────────────────────────────
// Deletes everywhere in the app are now SOFT (deletedAt set); this is the one
// place that restores or permanently purges them. Auto-purge after 30 days.
//
// TENANCY: these five kept reading `TRASH_MODELS[type]` directly while the other 65 actions in
// this file had already moved to `scoped()`, so in SaaS mode they listed, restored and
// PERMANENTLY DELETED out of the shared default database. `emptyTrash` is the sharp end: one
// workspace's "empty the trash" would sweep every workspace's trashed records, and unlike the
// settings-sharing bug that one is not reversible. They are gated first for that reason.
// `purgeTrashEntry` already routed its cross-reference cleanup through `scoped()` — the
// PRIMARY delete was the one going to the wrong database.

export type TrashRow = { type: TrashType; id: string; title: string; subtitle: string; deletedAt: string };
export type TrashType = 'item' | 'receipt' | 'expense' | 'subscription' | 'voucher' | 'giftcard' | 'loyaltycard' | 'bill' | 'goal' | 'task' | 'conversation';

const TRASH_MODELS: Record<TrashType, typeof Item> = {
  item: Item,
  receipt: Receipt as unknown as typeof Item,
  expense: Expense as unknown as typeof Item,
  subscription: Subscription as unknown as typeof Item,
  voucher: Voucher as unknown as typeof Item,
  giftcard: GiftCard as unknown as typeof Item,
  loyaltycard: LoyaltyCard as unknown as typeof Item,
  bill: Bill as unknown as typeof Item,
  goal: Goal as unknown as typeof Item,
  task: Task as unknown as typeof Item,
  conversation: Conversation as unknown as typeof Item,
};
const TRASH_RETENTION_DAYS = 30;

function trashLabel(type: TrashType, d: Record<string, unknown>, locale = 'en'): { title: string; subtitle: string } {
  switch (type) {
    case 'item': return { title: String(d.title || '—'), subtitle: String(d.category || '') };
    case 'receipt': return { title: String(d.store || '—'), subtitle: `€${d.total ?? 0} · ${formatDate(d.date as string, locale)}` };
    case 'expense': return { title: String(d.vendor || d.category || '—'), subtitle: `${d.kind} · €${d.amount ?? 0}` };
    case 'subscription': return { title: String(d.name || '—'), subtitle: `€${d.amount ?? 0}/${d.billingCycle || ''}` };
    case 'voucher': return { title: String(d.title || '—'), subtitle: String(d.store || '') };
    case 'giftcard': return { title: String(d.title || '—'), subtitle: `${d.store || ''} · €${d.initialAmount ?? 0}`.trim() };
    case 'loyaltycard': return { title: String(d.title || '—'), subtitle: String(d.store || '') };
    case 'bill': return { title: String(d.title || '—'), subtitle: `${d.vendor || ''} · €${d.amount ?? 0}`.trim() };
    case 'goal': return { title: String(d.title || '—'), subtitle: `€${d.targetAmount ?? 0}${d.targetDate ? ` · ${formatDate(d.targetDate as string, locale)}` : ''}` };
    case 'task': return { title: String(d.title || '—'), subtitle: String(d.status || '') };
    case 'conversation': return { title: String(d.title || 'Conversation'), subtitle: `${d.turns || 0} turn${d.turns === 1 ? '' : 's'}` };
  }
}

/** List everything in the Trash (and silently purge entries older than 30 days). */
export async function getTrash(): Promise<TrashRow[]> {
  await connectDB();
  const cutoff = new Date(Date.now() - TRASH_RETENTION_DAYS * 86400000);
  const locale = await getLocaleSafe();
  const rows: TrashRow[] = [];
  for (const [type, RawModel] of Object.entries(TRASH_MODELS) as [TrashType, typeof Item][]) {
    const Model = await scoped(RawModel);
    const docs = await Model.find({ deletedAt: { $ne: null } }).setOptions({ withDeleted: true }).lean();
    for (const d of docs as unknown as Record<string, unknown>[]) {
      const deletedAt = new Date(d.deletedAt as string);
      if (deletedAt < cutoff) {
        await purgeTrashEntry(type, String(d._id));
        continue;
      }
      const { title, subtitle } = trashLabel(type, d, locale);
      rows.push({ type, id: String(d._id), title, subtitle, deletedAt: deletedAt.toISOString() });
    }
  }
  return rows.sort((a, b) => new Date(b.deletedAt).getTime() - new Date(a.deletedAt).getTime());
}

/** Bring a trashed record back exactly as it was (files + links were never touched). */
export async function restoreFromTrash(type: TrashType, id: string): Promise<{ ok: boolean }> {
  await assertCanWrite();
  const RawModel = TRASH_MODELS[type];
  if (!RawModel) return { ok: false };
  await connectDB();
  const Model = await scoped(RawModel);
  await Model.updateOne({ _id: id }, { $set: { deletedAt: null } }).setOptions({ withDeleted: true });
  if (type === 'expense') {
    // #104: deleting released the expense's gift-card spend; bringing the expense back takes it
    // again, from the split the expense still carries.
    const e = (await Model.findById(id).lean()) as { paymentSplits?: PaymentSplitEntry[]; date?: Date; vendor?: string } | null;
    if (e) await syncGiftCardUses(id, cleanPaymentSplits(e.paymentSplits ?? []), e.date ? new Date(e.date) : new Date(), e.vendor || '');
  }
  revalidatePath('/', 'layout');
  return { ok: true };
}

/** Permanently delete: doc + its binary files + dangling cross-references.
 *  Admin-guarded entry point for server actions. */
export async function purgeFromTrash(type: TrashType, id: string): Promise<{ ok: boolean }> {
  await requireAdmin();
  return purgeTrashEntry(type, id);
}

/** Core purge logic WITHOUT an auth guard. Callers (server action or bearer API
 *  route) must authorize first; the API route enforces admin via the bearer user. */
export async function purgeTrashEntry(type: TrashType, id: string): Promise<{ ok: boolean }> {
  await assertCanWrite();
  const RawModel = TRASH_MODELS[type];
  if (!RawModel) return { ok: false };
  await connectDB();
  const Model = await scoped(RawModel);
  const doc = (await Model.findById(id).setOptions({ withDeleted: true }).lean()) as Record<string, unknown> | null;
  if (!doc) return { ok: true };
  const oid = new Types.ObjectId(id);

  if (type === 'receipt' || type === 'expense') {
    for (const fp of [doc.filePath, doc.thumbPath]) if (fp) await deleteFile(String(fp)).catch(() => {});
  }
  if (type === 'receipt') {
    await (await scoped(Item)).updateMany({ receiptIds: oid }, { $pull: { receiptIds: oid } });
  }
  if (type === 'item') {
    for (const p of (doc.photos as string[] | undefined) ?? []) await deleteFile(p).catch(() => {});
    for (const a of (doc.attachments as { path?: string }[] | undefined) ?? []) if (a.path) await deleteFile(a.path).catch(() => {});
    await (await scoped(Receipt)).updateMany({ itemIds: oid }, { $pull: { itemIds: oid } });
    await (await scoped(Receipt)).updateMany(
      { 'lineItems.matchedItemId': oid },
      { $set: { 'lineItems.$[el].matchedItemId': null } },
      { arrayFilters: [{ 'el.matchedItemId': oid }] }
    );
    await (await scoped(Statement)).updateMany(
      { 'transactions.matchedItemIds': oid },
      { $pull: { 'transactions.$[].matchedItemIds': oid } }
    );
  }
  await Model.deleteOne({ _id: id }).setOptions({ withDeleted: true });
  revalidatePath('/', 'layout');
  return { ok: true };
}

/** Empty the whole Trash (permanent). */
export async function emptyTrash(): Promise<{ ok: boolean; purged: number }> {
  await requireAdmin();
  await connectDB();
  let purged = 0;
  for (const [type, RawModel] of Object.entries(TRASH_MODELS) as [TrashType, typeof Item][]) {
    const Model = await scoped(RawModel);
    const docs = await Model.find({ deletedAt: { $ne: null } }).setOptions({ withDeleted: true }).select('_id').lean();
    for (const d of docs as unknown as { _id: unknown }[]) {
      await purgeTrashEntry(type, String(d._id));
      purged++;
    }
  }
  return { ok: true, purged };
}

// ─── OneDrive wizard (Microsoft Graph device-code auth) ──────────────────────

/** Step 1 of the wizard: get a device code for the user to enter at microsoft.com/devicelogin. */
export async function startOnedriveAuth(clientId: string): Promise<DeviceCode> {
  await requireAdmin();
  return startDeviceCode(clientId.trim());
}

/** Step 2: poll until the user finishes signing in (returns 'pending' meanwhile). */
export async function pollOnedriveAuth(clientId: string, deviceCode: string): Promise<{ status: 'ok' | 'pending' | 'error'; error?: string; account?: string }> {
  await assertCanWrite();
  const r = await pollDeviceToken(clientId.trim(), deviceCode);
  if (r.status === 'ok') {
    invalidateStorageConfig();
    revalidatePath('/settings');
  }
  return r;
}

export async function getOnedriveStatus(): Promise<{ connected: boolean; account: string }> {
  const c = await getOnedriveCreds();
  return { connected: !!c, account: c?.account || '' };
}

export async function disconnectOnedriveAccount(): Promise<{ ok: boolean }> {
  await requireAdmin();
  await disconnectOnedrive();
  invalidateStorageConfig();
  revalidatePath('/settings');
  return { ok: true };
}

export async function testOnedriveConnection(): Promise<{ ok: boolean; error?: string; drive?: string }> {
  return testOnedrive();
}

'use client';
import { useState, useRef, useTransition, useMemo } from 'react';
import { Camera, Plus, Check, Loader2, Trash2, Sparkles, ShoppingBasket, LayoutGrid, List as ListIcon, Search, SlidersHorizontal, CheckSquare, Repeat2 } from 'lucide-react';
import { cn } from '@/components/ui/cn';
import { Modal } from '@/components/ui/Modal';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { useT } from '@/components/LocaleProvider';
import { shrinkImage } from '@/lib/clientImage';
import { compareNames } from '@/lib/i18n/format';
import { useLocale } from '@/components/LocaleProvider';
import {
  addListItem,
  toggleListItem,
  deleteListItem,
  clearChecked,
  scanProductPhoto,
  getListItems,
  updateListItem,
  type SerializedListItem,
} from './actions';

type Draft = { name: string; quantity: string; category: string; brand: string; restockIntervalDays: string };
type StatusFilter = 'all' | 'todo' | 'bought';
type SortKey = 'recent' | 'name' | 'category';
const mono = { fontFamily: 'var(--font-mono)' };
const display = { fontFamily: 'var(--font-display)' }; // titles match every other page's cards
const emptyDraft: Draft = { name: '', quantity: '', category: '', brand: '', restockIntervalDays: '' };

// Deterministic category accent — gives each category a stable colour (like the product cards' eyebrows).
const PALETTE = ['var(--color-accent)', 'var(--color-cyan)', 'var(--color-purple)', 'var(--color-gold)', 'var(--color-red)'];
function catColor(cat: string): string | null {
  const c = cat.trim();
  if (!c) return null;
  let h = 0;
  for (let i = 0; i < c.length; i++) h = (h * 31 + c.charCodeAt(i)) >>> 0;
  return PALETTE[h % PALETTE.length];
}

export function ShoppingListClient({ initialItems }: { initialItems: SerializedListItem[] }) {
  const locale = useLocale();
  const t = useT();
  const [items, setItems] = useState<SerializedListItem[]>(initialItems);
  const [, start] = useTransition();
  const cameraRef = useRef<HTMLInputElement>(null);
  const idSeq = useRef(0); // collision-free temp ids for optimistic rows

  const [scanning, setScanning] = useState(false);
  const [scanErr, setScanErr] = useState<string | null>(null);
  const [draft, setDraft] = useState<Draft | null>(null);

  // Add modal (matches the "+ New" → modal pattern of the other pages)
  const [showAdd, setShowAdd] = useState(false);
  const [addForm, setAddForm] = useState<Draft>(emptyDraft);
  const [restockItem, setRestockItem] = useState<SerializedListItem | null>(null);
  const [restockDays, setRestockDays] = useState('');

  // E-shop layout state
  const [layout, setLayout] = useState<'grid' | 'list'>('grid');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [catFilter, setCatFilter] = useState('');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortKey>('recent');
  const [showFilters, setShowFilters] = useState(false);

  // Bulk select
  const [selectMode, setSelectMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const todo = useMemo(() => items.filter((i) => !i.checked), [items]);
  const done = useMemo(() => items.filter((i) => i.checked), [items]);
  const cats = useMemo(
    () => Array.from(new Set(items.map((i) => (i.category || '').trim()).filter(Boolean))).sort(),
    [items]
  );

  const visible = useMemo(() => {
    let list = items;
    if (statusFilter === 'todo') list = list.filter((i) => !i.checked);
    else if (statusFilter === 'bought') list = list.filter((i) => i.checked);
    if (catFilter) list = list.filter((i) => (i.category || '').toLowerCase() === catFilter.toLowerCase());
    const q = search.trim().toLowerCase();
    if (q) list = list.filter((i) => i.name.toLowerCase().includes(q) || (i.brand || '').toLowerCase().includes(q) || (i.category || '').toLowerCase().includes(q));
    return [...list].sort((a, b) => {
      const c = (a.checked ? 1 : 0) - (b.checked ? 1 : 0); // unchecked first
      if (c) return c;
      if (sortBy === 'name') return compareNames(a.name, b.name, locale);
      if (sortBy === 'category') return compareNames(a.category, b.category, locale) || compareNames(a.name, b.name, locale);
      return b.createdAt.localeCompare(a.createdAt);
    });
  }, [items, statusFilter, catFilter, search, sortBy]);

  async function resync() {
    try {
      setItems(await getListItems());
    } catch {
      /* keep optimistic state */
    }
  }

  function addItem(d: Draft, aiScanned = false) {
    const n = d.name.trim();
    if (!n) return;
    const clean = { name: n, quantity: d.quantity.trim(), category: d.category.trim(), brand: d.brand.trim(), aiScanned, restockIntervalDays: d.restockIntervalDays ? Number(d.restockIntervalDays) : undefined };
    // Make sure the new row is actually visible (a stale status/category filter would
    // otherwise hide it → it looks like "I added it but it disappeared").
    setStatusFilter('all');
    setCatFilter('');
    setScanErr(null);
    const tmpId = 'tmp-' + Date.now() + '-' + idSeq.current++;
    const tmp: SerializedListItem = {
      _id: tmpId, ...clean, restockIntervalDays: clean.restockIntervalDays ?? null, note: '', checked: false, createdAt: new Date().toISOString(),
      lastRestockedAt: null,
    };
    setItems((p) => [tmp, ...p]);
    start(async () => {
      try {
        const r = await addListItem(clean);
        if (!r.ok) throw new Error(r.error || 'Could not save');
        await resync(); // replace the optimistic row with the saved one
      } catch (e) {
        // Roll the optimistic row back and surface the error instead of leaving a
        // phantom that vanishes on the next load.
        setItems((p) => p.filter((x) => x._id !== tmpId));
        setScanErr((e as Error).message.slice(0, 140));
      }
    });
  }

  function submitAdd() {
    if (!addForm.name.trim()) return;
    addItem(addForm);
    setShowAdd(false);
    setAddForm(emptyDraft);
  }

  function toggle(it: SerializedListItem) {
    const next = !it.checked;
    setItems((p) => p.map((x) => (x._id === it._id ? { ...x, checked: next } : x)));
    start(() => void toggleListItem(it._id, next));
  }
  function remove(it: SerializedListItem) {
    setItems((p) => p.filter((x) => x._id !== it._id));
    start(() => void deleteListItem(it._id));
  }
  function clearBought() {
    setItems((p) => p.filter((x) => !x.checked));
    start(() => void clearChecked());
  }

  function saveRestock() {
    if (!restockItem) return;
    const value = restockDays ? Number(restockDays) : null;
    if (value !== null && (!Number.isInteger(value) || value < 1 || value > 3650)) return;
    const id = restockItem._id;
    setItems((p) => p.map((x) => x._id === id ? { ...x, restockIntervalDays: value } : x));
    setRestockItem(null);
    start(() => void updateListItem(id, { restockIntervalDays: value }));
  }

  // Bulk select
  function toggleSelect(id: string) {
    setSelectedIds((p) => {
      const n = new Set(p);
      if (n.has(id)) n.delete(id); else n.add(id);
      return n;
    });
  }
  function exitSelect() {
    setSelectMode(false);
    setSelectedIds(new Set());
  }
  function bulkDelete() {
    const ids = [...selectedIds];
    if (!ids.length) return;
    setItems((p) => p.filter((x) => !selectedIds.has(x._id)));
    exitSelect();
    start(async () => {
      for (const id of ids) await deleteListItem(id);
      await resync();
    });
  }
  function bulkBought() {
    const ids = [...selectedIds];
    if (!ids.length) return;
    setItems((p) => p.map((x) => (selectedIds.has(x._id) ? { ...x, checked: true } : x)));
    exitSelect();
    start(async () => {
      for (const id of ids) await toggleListItem(id, true);
      await resync();
    });
  }

  async function onPhoto(file: File | undefined) {
    if (cameraRef.current) cameraRef.current.value = '';
    if (!file) return;
    setScanErr(null);
    setScanning(true);
    try {
      const small = await shrinkImage(file);
      const fd = new FormData();
      fd.set('file', small);
      const r = await scanProductPhoto(fd);
      if (r.ok) setDraft({ name: r.data.name, quantity: r.data.quantity, category: r.data.category, brand: r.data.brand, restockIntervalDays: '' });
      else setScanErr(r.error);
    } catch (e) {
      setScanErr((e as Error).message.slice(0, 120));
    } finally {
      setScanning(false);
    }
  }

  function addDraft() {
    if (!draft || !draft.name.trim()) return;
    const d = draft;
    setDraft(null);
    addItem(d, true); // optimistic + persist + rollback-on-failure, marked AI-scanned
  }

  const fLabel = 'text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-[0.12em] mb-1.5';
  const selCls =
    'w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg px-3 py-1.5 text-xs text-[color:var(--color-text-dim)] focus:outline-none focus:border-[color:var(--color-accent)]';
  const statusLabel = (v: StatusFilter) => (v === 'all' ? t('common.all') : v === 'todo' ? t('sl.fToBuy') : t('sl.fBought'));
  const anyF = statusFilter !== 'all' || !!catFilter || !!search || sortBy !== 'recent';

  const filterControls = (
    <div className="space-y-4">
      <Input icon={<Search size={14} />} placeholder={t('common.search')} value={search} onChange={(e) => setSearch(e.target.value)} />
      <div>
        <p className={fLabel} style={mono}>{t('common.status')}</p>
        <div className="flex flex-col gap-1">
          {(['all', 'todo', 'bought'] as const).map((v) => (
            <button
              key={v}
              onClick={() => setStatusFilter(v)}
              className={cn(
                'text-left px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
                statusFilter === v ? 'bg-[color:var(--color-accent)] text-black' : 'text-[color:var(--color-text-dim)] hover:bg-[color:var(--color-surface-2)] hover:text-[color:var(--color-text)]'
              )}
              style={mono}
            >
              {statusLabel(v)}
            </button>
          ))}
        </div>
      </div>
      {cats.length > 0 && (
        <div>
          <p className={fLabel} style={mono}>{t('common.category')}</p>
          <select value={catFilter} onChange={(e) => setCatFilter(e.target.value)} className={selCls} style={mono}>
            <option value="">{t('common.all')}</option>
            {cats.map((c) => (
              <option key={c} value={c}>{c}</option>
            ))}
          </select>
        </div>
      )}
      <div>
        <p className={fLabel} style={mono}>{t('common.sort')}</p>
        <select value={sortBy} onChange={(e) => setSortBy(e.target.value as SortKey)} className={selCls} style={mono}>
          <option value="recent">{t('sl.sortRecent')}</option>
          <option value="name">{t('sl.sortName')}</option>
          <option value="category">{t('common.category')}</option>
        </select>
      </div>
      {anyF && (
        <button
          onClick={() => { setStatusFilter('all'); setCatFilter(''); setSearch(''); setSortBy('recent'); }}
          className="text-[0.65rem] text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] underline"
          style={mono}
        >
          reset filters
        </button>
      )}
    </div>
  );

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-6 pb-24">
      <div className="mb-5 flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold" style={{ fontFamily: 'var(--font-display)' }}>
            {t('nav.shoppingList')}
            {todo.length > 0 && (
              <span className="ml-3 text-sm font-normal text-[color:var(--color-text-faint)]" style={mono}>
                {t('sl.toBuy', { n: todo.length })}
              </span>
            )}
          </h1>
        </div>

        {selectMode ? (
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm text-[color:var(--color-text-dim)]" style={mono}>{t('sl.selected', { n: selectedIds.size })}</span>
            <Button variant="secondary" size="sm" onClick={bulkBought} disabled={!selectedIds.size}>
              <Check size={14} /> {t('sl.markBought')}
            </Button>
            <Button variant="danger" size="sm" onClick={bulkDelete} disabled={!selectedIds.size}>
              <Trash2 size={14} /> {t('common.delete')}
            </Button>
            <Button variant="ghost" size="sm" onClick={exitSelect}>{t('common.cancel')}</Button>
          </div>
        ) : (
          <div className="flex items-center gap-2 flex-wrap">
            <div className="flex bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg p-0.5">
              {(['grid', 'list'] as const).map((v) => (
                <button
                  key={v}
                  onClick={() => setLayout(v)}
                  title={v === 'grid' ? t('v.grid') : t('v.list')}
                  className={cn('px-2 py-1.5 rounded-md transition-colors', layout === v ? 'bg-[color:var(--color-accent)] text-black' : 'text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)]')}
                >
                  {v === 'grid' ? <LayoutGrid size={14} /> : <ListIcon size={14} />}
                </button>
              ))}
            </div>
            {items.length > 0 && (
              <Button variant="ghost" size="sm" onClick={() => setSelectMode(true)}>
                <CheckSquare size={14} /> {t('sl.select')}
              </Button>
            )}
            <Button variant="secondary" onClick={() => cameraRef.current?.click()} disabled={scanning}>
              {scanning ? <Loader2 size={16} className="animate-spin" /> : <Camera size={16} />} {scanning ? t('sl.scanning') : t('sl.scanProduct')}
            </Button>
            <Button variant="primary" onClick={() => { setAddForm(emptyDraft); setShowAdd(true); }}>
              <Plus size={16} strokeWidth={2.5} /> {t('common.new')}
            </Button>
          </div>
        )}
        <input ref={cameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={(e) => onPhoto(e.target.files?.[0])} />
      </div>

      {/* E-shop body: filter sidebar + items */}
      <div className="flex gap-6 items-start">
        <aside className="hidden lg:block w-56 shrink-0 sticky top-4 self-start">{filterControls}</aside>

        <div className="flex-1 min-w-0">
          {/* Mobile filter toggle + drawer */}
          <div className="lg:hidden mb-4">
            <button
              onClick={() => setShowFilters((v) => !v)}
              className="flex items-center gap-1.5 text-xs px-3 py-2 rounded-lg bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] text-[color:var(--color-text-dim)]"
              style={mono}
            >
              <SlidersHorizontal size={14} /> Filters {anyF && <span className="text-[color:var(--color-accent)]">•</span>}
            </button>
            {showFilters && <div className="mt-3 p-3 rounded-xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)]">{filterControls}</div>}
          </div>

          {scanErr && <p className="mb-3 text-xs text-[color:var(--color-red)]">{scanErr}</p>}

          {/* Items */}
          {visible.length === 0 ? (
            <div className="text-center py-20 text-[color:var(--color-text-faint)]">
              <ShoppingBasket size={40} className="mx-auto mb-3 opacity-40" />
              <p className="text-sm">{items.length === 0 ? t('sl.empty') : t('sl.noMatch')}</p>
            </div>
          ) : (
            <div className={cn(layout === 'grid' ? 'grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3' : 'flex flex-col gap-2')}>
              {visible.map((it) =>
                layout === 'grid' ? (
                  <Card key={it._id} it={it} color={catColor(it.category)} selectMode={selectMode} selected={selectedIds.has(it._id)} onSelect={() => toggleSelect(it._id)} onToggle={() => toggle(it)} onRemove={() => remove(it)} onRestock={() => { setRestockItem(it); setRestockDays(it.restockIntervalDays?.toString() ?? ''); }} />
                ) : (
                  <Row key={it._id} it={it} color={catColor(it.category)} selectMode={selectMode} selected={selectedIds.has(it._id)} onSelect={() => toggleSelect(it._id)} onToggle={() => toggle(it)} onRemove={() => remove(it)} onRestock={() => { setRestockItem(it); setRestockDays(it.restockIntervalDays?.toString() ?? ''); }} />
                )
              )}
            </div>
          )}

          {done.length > 0 && statusFilter !== 'todo' && !selectMode && (
            <div className="mt-5 text-right">
              <button onClick={clearBought} className="text-[11px] text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)]" style={mono}>
                {t('sl.clearBought')}
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Add an item (matches the other pages' "+ New" modal) */}
      {showAdd && (
        <Modal open onClose={() => setShowAdd(false)} title={t('sl.addTitle')} size="sm">
          <div className="space-y-3">
            <Field label={t('sl.name')}>
              <input autoFocus value={addForm.name} onChange={(e) => setAddForm({ ...addForm, name: e.target.value })} onKeyDown={(e) => { if (e.key === 'Enter') submitAdd(); }} className={inputCls} />
            </Field>
            <div className="grid grid-cols-2 gap-3">
              <Field label={t('sl.qty')}>
                <input value={addForm.quantity} onChange={(e) => setAddForm({ ...addForm, quantity: e.target.value })} onKeyDown={(e) => { if (e.key === 'Enter') submitAdd(); }} className={inputCls} />
              </Field>
              <Field label={t('sl.category')}>
                <input value={addForm.category} onChange={(e) => setAddForm({ ...addForm, category: e.target.value })} onKeyDown={(e) => { if (e.key === 'Enter') submitAdd(); }} className={inputCls} />
              </Field>
            </div>
            <Field label={t('sl.brand')}>
              <input value={addForm.brand} onChange={(e) => setAddForm({ ...addForm, brand: e.target.value })} onKeyDown={(e) => { if (e.key === 'Enter') submitAdd(); }} className={inputCls} />
            </Field>
            <Field label={t('sl.restockDays')}>
              <input type="number" min="1" max="3650" step="1" placeholder={t('sl.restockPlaceholder')} value={addForm.restockIntervalDays} onChange={(e) => setAddForm({ ...addForm, restockIntervalDays: e.target.value })} className={inputCls} />
            </Field>
            <div className="flex items-center gap-2 pt-1">
              <Button variant="primary" onClick={submitAdd} disabled={!addForm.name.trim()}>
                <Plus size={15} /> {t('common.add')}
              </Button>
              <Button variant="ghost" onClick={() => setShowAdd(false)}>{t('common.cancel')}</Button>
            </div>
          </div>
        </Modal>
      )}

      {restockItem && (
        <Modal open onClose={() => setRestockItem(null)} title={t('sl.restockTitle')} size="sm">
          <div className="space-y-3">
            <p className="text-xs text-[color:var(--color-text-dim)]">{t('sl.restockHint')}</p>
            <Field label={t('sl.restockDays')}>
              <input autoFocus type="number" min="1" max="3650" step="1" placeholder={t('sl.restockPlaceholder')} value={restockDays} onChange={(e) => setRestockDays(e.target.value)} className={inputCls} />
            </Field>
            <div className="flex gap-2"><Button variant="primary" onClick={saveRestock}>{t('common.save')}</Button><Button variant="ghost" onClick={() => setRestockItem(null)}>{t('common.cancel')}</Button></div>
          </div>
        </Modal>
      )}

      {/* Verify a scanned product before adding */}
      {draft && (
        <Modal open onClose={() => setDraft(null)} title={t('sl.verifyTitle')} size="sm">
          <div className="space-y-3">
            <p className="text-xs text-[color:var(--color-text-dim)] flex items-center gap-1.5">
              <Sparkles size={13} className="text-[color:var(--color-accent)]" /> {t('sl.verifyHint')}
            </p>
            <Field label={t('sl.name')}>
              <input autoFocus value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} className={inputCls} />
            </Field>
            <div className="grid grid-cols-2 gap-3">
              <Field label={t('sl.qty')}>
                <input value={draft.quantity} onChange={(e) => setDraft({ ...draft, quantity: e.target.value })} className={inputCls} />
              </Field>
              <Field label={t('sl.category')}>
                <input value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })} className={inputCls} />
              </Field>
            </div>
            <Field label={t('sl.brand')}>
              <input value={draft.brand} onChange={(e) => setDraft({ ...draft, brand: e.target.value })} className={inputCls} />
            </Field>
            <div className="flex items-center gap-2 pt-1">
              <Button variant="primary" onClick={addDraft} disabled={!draft.name.trim()}>
                <Check size={15} /> {t('sl.addToList')}
              </Button>
              <Button variant="ghost" onClick={() => setDraft(null)}>{t('common.cancel')}</Button>
            </div>
          </div>
        </Modal>
      )}
    </main>
  );
}

const inputCls =
  'w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg px-3 py-2 text-sm outline-none focus:border-[color:var(--color-accent)]';

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="block">
      <span className="block text-[10px] uppercase tracking-wider text-[color:var(--color-text-faint)] mb-1" style={mono}>{label}</span>
      {children}
    </label>
  );
}

function Box({ checked, accent, onClick }: { checked: boolean; accent: boolean; onClick?: (e: React.MouseEvent) => void }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'shrink-0 grid place-items-center w-6 h-6 rounded-md border transition-colors',
        checked ? 'bg-[color:var(--color-accent)] border-[color:var(--color-accent)] text-black' : accent ? 'border-[color:var(--color-accent)]' : 'border-[color:var(--color-border-light)] hover:border-[color:var(--color-accent)]'
      )}
      aria-label="toggle"
    >
      {checked && <Check size={14} strokeWidth={3} />}
    </button>
  );
}

/** Mono uppercase category eyebrow — the same treatment as the inventory cards' eyebrow. */
function Eyebrow({ category, color }: { category: string; color: string | null }) {
  if (!category) return null;
  return (
    <span className="block text-[11px] uppercase tracking-[0.08em] mb-0.5 truncate" style={{ ...mono, color: color || 'var(--color-text-faint)' }}>
      {category}
    </span>
  );
}

function Meta({ it }: { it: SerializedListItem }) {
  if (!it.quantity && !it.aiScanned && !it.restockIntervalDays) return null;
  return (
    <div className="flex flex-wrap items-center gap-1.5 mt-2">
      {it.quantity && <span className="text-[10px] px-1.5 py-0.5 rounded bg-[color:var(--color-surface-2)] text-[color:var(--color-text-dim)]" style={mono}>{it.quantity}</span>}
      {it.aiScanned && <span className="text-[10px] text-[color:var(--color-accent)] flex items-center gap-0.5" style={mono}><Sparkles size={9} /> AI</span>}
      {it.restockIntervalDays && <span className="text-[10px] text-[color:var(--color-text-faint)]" style={mono}>↻ {it.restockIntervalDays}d</span>}
    </div>
  );
}

type CardProps = {
  it: SerializedListItem;
  color: string | null;
  selectMode: boolean;
  selected: boolean;
  onSelect: () => void;
  onToggle: () => void;
  onRemove: () => void;
  onRestock?: () => void;
};

/** Grid card — colour-coded by category, mirroring the product-card surface used across the app. */
function Card({ it, color, selectMode, selected, onSelect, onToggle, onRemove, onRestock }: CardProps) {
  const struck = it.checked && !selectMode;
  return (
    <div
      onClick={selectMode ? onSelect : undefined}
      className={cn(
        'group relative flex items-start gap-3 bg-[color:var(--color-surface)] border rounded-2xl p-4 pl-5 min-h-[84px] overflow-hidden transition-colors',
        selectMode && 'cursor-pointer',
        selected ? 'border-[color:var(--color-accent)] ring-1 ring-[color:var(--color-accent)]' : 'border-[color:var(--color-border)] hover:border-[color:var(--color-border-light)]',
        it.checked && !selected && 'opacity-60'
      )}
    >
      {color && <span className="absolute left-0 top-0 bottom-0 w-1" style={{ background: color }} />}
      <Box checked={selectMode ? selected : it.checked} accent={selectMode && selected} onClick={selectMode ? undefined : (e) => { e.stopPropagation(); onToggle(); }} />
      <div className={cn('min-w-0 flex-1', !selectMode && 'cursor-pointer')} onClick={selectMode ? undefined : onToggle}>
        <Eyebrow category={it.category} color={color} />
        <span className={cn('block text-sm font-semibold leading-snug break-words', struck && 'line-through')} style={display}>{it.name}</span>
        {it.brand && <span className="block text-xs text-[color:var(--color-text-faint)] mt-0.5 truncate">{it.brand}</span>}
        <Meta it={it} />
      </div>
      {!selectMode && (
        <div className="flex flex-col"><button onClick={(e) => { e.stopPropagation(); onRestock?.(); }} className="p-1.5 text-[color:var(--color-text-faint)] hover:text-[color:var(--color-accent)] opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 focus:opacity-100" aria-label="restock"><Repeat2 size={14} /></button><button onClick={(e) => { e.stopPropagation(); onRemove(); }} className="p-1.5 text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 focus:opacity-100" aria-label="remove"><Trash2 size={14} /></button></div>
      )}
    </div>
  );
}

/** List row — compact full-width line, same behaviour as the card. */
function Row({ it, color, selectMode, selected, onSelect, onToggle, onRemove, onRestock }: CardProps) {
  const struck = it.checked && !selectMode;
  return (
    <div
      onClick={selectMode ? onSelect : undefined}
      className={cn(
        'group relative flex items-center gap-3 bg-[color:var(--color-surface)] border rounded-xl pl-4 pr-3 py-2.5 overflow-hidden transition-colors',
        selectMode && 'cursor-pointer',
        selected ? 'border-[color:var(--color-accent)] ring-1 ring-[color:var(--color-accent)]' : 'border-[color:var(--color-border)] hover:border-[color:var(--color-border-light)]',
        it.checked && !selected && 'opacity-60'
      )}
    >
      {color && <span className="absolute left-0 top-0 bottom-0 w-1" style={{ background: color }} />}
      <Box checked={selectMode ? selected : it.checked} accent={selectMode && selected} onClick={selectMode ? undefined : (e) => { e.stopPropagation(); onToggle(); }} />
      <div className={cn('min-w-0 flex-1', !selectMode && 'cursor-pointer')} onClick={selectMode ? undefined : onToggle}>
        <span className={cn('block text-sm font-semibold truncate', struck && 'line-through')} style={display}>
          {it.name}
          {it.brand && <span className="text-[color:var(--color-text-faint)] font-normal"> · {it.brand}</span>}
        </span>
        {(it.quantity || it.category) && (
          <span className="flex items-center gap-2 mt-0.5">
            {it.category && <span className="text-[10px] uppercase tracking-[0.08em]" style={{ ...mono, color: color || 'var(--color-text-faint)' }}>{it.category}</span>}
            {it.quantity && <span className="text-[10px] px-1.5 py-0.5 rounded bg-[color:var(--color-surface-2)] text-[color:var(--color-text-dim)]" style={mono}>{it.quantity}</span>}
          </span>
        )}
      </div>
      {!selectMode && (
        <div className="flex"><button onClick={(e) => { e.stopPropagation(); onRestock?.(); }} className="p-1.5 text-[color:var(--color-text-faint)] hover:text-[color:var(--color-accent)] opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 focus:opacity-100" aria-label="restock"><Repeat2 size={15} /></button><button onClick={(e) => { e.stopPropagation(); onRemove(); }} className="p-1.5 text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 focus:opacity-100" aria-label="remove"><Trash2 size={15} /></button></div>
      )}
    </div>
  );
}

