} from './actions';

const CATEGORIES = [
  { value: 'streaming', label: 'Streaming', hex: '#a55eea' },
  { value: 'cloud', label: 'Cloud', hex: '#00d4ff' },
  { value: 'software', label: 'Software', hex: '#00ff88' },
