  receipt: { labelKey: 'trash.tReceipt', Icon: ReceiptIcon },
  expense: { labelKey: 'trash.tExpense', Icon: Wallet },
  subscription: { labelKey: 'trash.tSubscription', Icon: CalendarClock },
  voucher: { labelKey: 'trash.tVoucher', Icon: Ticket },
  giftcard: { labelKey: 'trash.tGiftCard', Icon: CreditCard },
  loyaltycard: { labelKey: 'trash.tLoyaltyCard', Icon: Barcode },
  bill: { labelKey: 'trash.tBill', Icon: FileText },
  goal: { labelKey: 'trash.tGoal', Icon: Target },
  task: { labelKey: 'trash.tTask', Icon: CheckSquare },
  conversation: { labelKey: 'trash.tConversation', Icon: Bot },
};

// 30-day retention (mirrors getTrash); show how long until auto-purge.
function purgesIn(iso: string): number {
  const d = (new Date(iso).getTime() + 30 * 86400000 - Date.now()) / 86400000;
  return Math.max(0, Math.ceil(d));
}

const key = (r: { type: TrashType; id: string }) => `${r.type}:${r.id}`;

export function TrashClient({ rows }: { rows: TrashRow[] }) {
  const router = useRouter();
  const confirm = useConfirm();
  const t = useT();
  const [pending, start] = useTransition();
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<TrashType | 'all'>('all');
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [busy, setBusy] = useState<string | null>(null);

  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const r of rows) c[r.type] = (c[r.type] ?? 0) + 1;
    return c;
  }, [rows]);

  const visible = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows.filter(
      (r) =>
        (typeFilter === 'all' || r.type === typeFilter) &&
        (!q || r.title.toLowerCase().includes(q) || r.subtitle.toLowerCase().includes(q) || r.type.includes(q))
    );
  }, [rows, search, typeFilter]);

  const allVisibleSelected = visible.length > 0 && visible.every((r) => selected.has(key(r)));

  function toggle(r: TrashRow) {
    setSelected((s) => {
      const n = new Set(s);
      const k = key(r);
      n.has(k) ? n.delete(k) : n.add(k);
      return n;
    });
  }
  function toggleAll() {
    setSelected((s) => {
      if (allVisibleSelected) {
        const n = new Set(s);
        visible.forEach((r) => n.delete(key(r)));
        return n;
      }
      return new Set([...s, ...visible.map(key)]);
    });
  }

  async function restore(r: TrashRow) {
    setBusy(key(r));
    await restoreFromTrash(r.type, r.id);
    setBusy(null);
    setSelected((s) => { const n = new Set(s); n.delete(key(r)); return n; });
    router.refresh();
  }

  async function purge(r: TrashRow) {
    const ok = await confirm({ title: t('trash.confirmDelete', { title: r.title }), message: t('trash.confirmDeleteBody'), confirmLabel: t('common.deleteForever'), danger: true });
    if (!ok) return;
    setBusy(key(r));
    await purgeFromTrash(r.type, r.id);
    setBusy(null);
    setSelected((s) => { const n = new Set(s); n.delete(key(r)); return n; });
    router.refresh();
  }

  function selectedRows(): TrashRow[] {
    return rows.filter((r) => selected.has(key(r)));
  }

  function restoreSelected() {
    const sel = selectedRows();
    if (!sel.length) return;
    start(async () => {
      for (const r of sel) await restoreFromTrash(r.type, r.id);
      setSelected(new Set());
      router.refresh();
    });
  }

  async function purgeSelected() {
    const sel = selectedRows();
    if (!sel.length) return;
    const ok = await confirm({ title: t('trash.confirmDeleteMany', { n: sel.length }), message: t('trash.confirmDeleteBody'), confirmLabel: t('common.deleteForever'), danger: true });
    if (!ok) return;
    start(async () => {
      for (const r of sel) await purgeFromTrash(r.type, r.id);
      setSelected(new Set());
      router.refresh();
    });
  }

  async function empty() {
    const ok = await confirm({ title: t('trash.confirmEmpty'), message: t('trash.confirmEmptyBody'), confirmLabel: t('trash.empty'), danger: true });
    if (!ok) return;
    start(async () => {
      await emptyTrash();
      setSelected(new Set());
      router.refresh();
    });
  }

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-6 pb-24">
      {/* Header */}
      <div className="flex items-end justify-between gap-4 flex-wrap mb-1">
        <h1 className="text-2xl md:text-3xl font-bold flex items-center gap-2.5" style={{ fontFamily: 'var(--font-display)' }}>
          <Trash2 size={26} className="text-[color:var(--color-text-dim)]" />
          {t('nav.trash')}
          <span className="text-sm font-normal text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
            {rows.length}
          </span>
        </h1>
        {rows.length > 0 && (
          <Button variant="danger" size="sm" onClick={empty} disabled={pending}>
            <Trash2 size={14} /> {t('trash.empty')}
          </Button>
        )}
      </div>
      <p className="text-xs text-[color:var(--color-text-faint)] mb-5">
        {t('trash.intro')}
      </p>

      {rows.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-[color:var(--color-border)] py-20 text-center">
          <Trash2 size={32} className="mx-auto text-[color:var(--color-text-faint)] opacity-40" />
          <p className="mt-3 text-sm text-[color:var(--color-text-dim)]">{t('trash.isEmpty')}</p>
          <p className="text-xs text-[color:var(--color-text-faint)]">{t('trash.emptyHint')}</p>
        </div>
      ) : (
        <>
          {/* Filters */}
          <div className="flex items-center gap-2 flex-wrap mb-4">
            <div className="relative flex-1 min-w-[180px]">
              <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[color:var(--color-text-faint)]" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={t('trash.searchPlaceholder')}
                className="w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg pl-8 pr-3 py-1.5 text-sm outline-none focus:border-[color:var(--color-accent)]"
              />
            </div>
          </div>
          <div className="flex items-center gap-1.5 flex-wrap mb-4" style={{ fontFamily: 'var(--font-mono)' }}>
            <Chip active={typeFilter === 'all'} onClick={() => setTypeFilter('all')} label={`${t('common.all')} ${rows.length}`} />
            {(Object.keys(TYPE_META) as TrashType[])
              .filter((ty) => counts[ty])
              .map((ty) => (
                <Chip key={ty} active={typeFilter === ty} onClick={() => setTypeFilter(ty)} label={`${t(TYPE_META[ty].labelKey)} ${counts[ty]}`} />
              ))}
          </div>

          {/* Bulk bar */}
          <div className="flex items-center justify-between gap-3 mb-3 text-xs">
            <button onClick={toggleAll} className="text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)]" style={{ fontFamily: 'var(--font-mono)' }}>
              {allVisibleSelected ? t('common.deselectAll') : t('trash.selectAllN', { n: visible.length })}
            </button>
            {selected.size > 0 && (
              <div className="flex items-center gap-2">
                <span className="text-[color:var(--color-text-faint)]">{t('trash.selected', { n: selected.size })}</span>
                <Button variant="secondary" size="sm" onClick={restoreSelected} disabled={pending}>
                  <RotateCcw size={13} /> {t('common.restore')}
                </Button>
                <Button variant="danger" size="sm" onClick={purgeSelected} disabled={pending}>
                  <Trash2 size={13} /> {t('common.delete')}
                </Button>
              </div>
            )}
          </div>

          {/* List */}
          <div className="space-y-1.5">
            {visible.map((r) => {
              const k = key(r);
              const { Icon } = TYPE_META[r.type];
              const isBusy = busy === k;
              const sel = selected.has(k);
              const left = purgesIn(r.deletedAt);
              return (
                <div
                  key={k}
                  className={cn(
                    'flex items-center gap-3 rounded-xl border px-3 py-2.5 transition-colors',
                    sel ? 'border-[color:var(--color-accent)] bg-[color:var(--color-accent)]/5' : 'border-[color:var(--color-border)] bg-[color:var(--color-surface)] hover:border-[color:var(--color-border-light)]'
                  )}
                >
                  <input type="checkbox" checked={sel} onChange={() => toggle(r)} className="shrink-0 accent-[color:var(--color-accent)] w-4 h-4" />
                  <Icon size={16} className="shrink-0 text-[color:var(--color-text-faint)]" />
                  <div className="min-w-0 flex-1">
                    <div className="text-sm font-medium truncate">{r.title}</div>
                    <div className="text-[11px] text-[color:var(--color-text-faint)] truncate" style={{ fontFamily: 'var(--font-mono)' }}>
                      {r.subtitle ? `${r.subtitle} · ` : ''}{t('trash.deleted', { ago: relTime(r.deletedAt, t) })}{left <= 7 ? ` · ${t('trash.purgesIn', { n: left })}` : ''}
                    </div>
                  </div>
                  <button
                    onClick={() => restore(r)}
                    disabled={isBusy}
                    title={t('common.restore')}
                    className="shrink-0 grid place-items-center w-8 h-8 rounded-lg text-[color:var(--color-text-dim)] hover:text-[color:var(--color-accent)] hover:bg-[color:var(--color-surface-2)] transition-colors"
                  >
                    {isBusy ? <Loader2 size={15} className="animate-spin" /> : <RotateCcw size={15} />}
                  </button>
                  <button
                    onClick={() => purge(r)}
                    disabled={isBusy}
                    title={t('common.deleteForever')}
                    className="shrink-0 grid place-items-center w-8 h-8 rounded-lg text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] hover:bg-[color:var(--color-surface-2)] transition-colors"
                  >
                    <X size={16} />
                  </button>
                </div>
              );
            })}
            {visible.length === 0 && (
              <p className="text-center text-sm text-[color:var(--color-text-faint)] py-10">{t('trash.noMatch')}</p>
            )}
          </div>
        </>
      )}
    </main>
  );
}

function Chip({ active, onClick, label }: { active: boolean; onClick: () => void; label: string }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'px-2.5 py-1 rounded-lg text-[11px] uppercase tracking-wide border transition-colors',
        active
          ? 'bg-[color:var(--color-accent)]/15 border-[color:var(--color-accent)]/40 text-[color:var(--color-accent)]'
          : 'border-[color:var(--color-border)] text-[color:var(--color-text-faint)] hover:text-[color:var(--color-text)]'
      )}
    >
      {label}
    </button>
  );
}

'use client';
import { useState, useTransition, useMemo } from 'react';
import { Plus, Trash2, CreditCard, Minus, Archive, ArchiveRestore, Clock } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { useConfirm } from '@/components/ui/ConfirmDialog';
import { cn } from '@/components/ui/cn';
import { useOpenParam } from '@/components/useOpenParam';
import { cur } from '@/lib/money';
import { giftCardBalance, giftCardSpentPct, giftCardDaysLeft } from '@/lib/giftcard';
import type { SerializedGiftCard } from '@/types';
import { createGiftCard, updateGiftCard, deleteGiftCard, setGiftCardArchived, addGiftCardUse, removeGiftCardUse } from './giftcardActions';
import { formatDate, formatTime, formatDateTime } from '@/lib/i18n/format';
import { useLocale } from '@/components/LocaleProvider';

const money = (n: number) => `${cur()}${n.toFixed(2)}`;

function ExpiryBadge({ expiresAt }: { expiresAt: string | null }) {
  const d = giftCardDaysLeft(expiresAt);
  if (d === null) return null;
  const expired = d < 0;
  const soon = d >= 0 && d <= 30;
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded font-semibold',
        expired
          ? 'bg-[color:var(--color-red)]/15 text-[color:var(--color-red)]'
          : soon
            ? 'bg-[color:var(--color-gold)]/15 text-[color:var(--color-gold)]'
            : 'bg-[color:var(--color-surface-2)] text-[color:var(--color-text-faint)]'
      )}
      style={{ fontFamily: 'var(--font-mono)' }}
    >
      <Clock size={10} /> {expired ? 'expired' : d === 0 ? 'today' : `${d}d left`}
    </span>
  );
}

export function GiftCardsClient({ giftCards }: { giftCards: SerializedGiftCard[] }) {
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing] = useState<SerializedGiftCard | null>(null);
  const [showArchived, setShowArchived] = useState(false);

  // Deep-link from global search: /vouchers?tab=giftcards&open=<id> (the shell picks the tab).
  useOpenParam((id) => {
    const g = giftCards.find((x) => x._id === id);
    // An archived / fully-spent card is hidden behind the "show archived" toggle, so reveal it
    // too — otherwise the search hit opens a modal over a list that appears not to contain it.
    if (g) {
      if (g.archived) setShowArchived(true);
      setEditing(g);
    }
  });

  const live = useMemo(() => giftCards.filter((g) => !g.archived && giftCardBalance(g.initialAmount, g.uses) > 0.009), [giftCards]);
  const totalUnspent = useMemo(() => live.reduce((s, g) => s + giftCardBalance(g.initialAmount, g.uses), 0), [live]);
  const visible = useMemo(() => giftCards.filter((g) => showArchived || (!g.archived && giftCardBalance(g.initialAmount, g.uses) > 0.009)), [giftCards, showArchived]);

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-6 pb-24">
      <div className="mb-5 flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold" style={{ fontFamily: 'var(--font-display)' }}>
            Gift cards
            <span className="ml-3 text-sm font-normal text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
              {live.length} active
            </span>
          </h1>
          {totalUnspent > 0 && (
            <p className="mt-1 text-sm text-[color:var(--color-text-dim)]">
              <span className="text-[color:var(--color-accent)] font-semibold">{money(totalUnspent)}</span> unspent across {live.length} card{live.length === 1 ? '' : 's'}
            </p>
          )}
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowArchived((v) => !v)}
            className={cn(
              'text-xs px-3 py-2 rounded-lg border transition-colors',
              showArchived ? 'border-[color:var(--color-accent)] text-[color:var(--color-accent)]' : 'border-[color:var(--color-border)] text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)]'
            )}
            style={{ fontFamily: 'var(--font-mono)' }}
          >
            {showArchived ? 'Hide' : 'Show'} empty/archived
          </button>
          <Button variant="primary" onClick={() => setShowCreate(true)}>
            <Plus size={16} strokeWidth={2.5} /> New card
          </Button>
        </div>
      </div>

      {visible.length === 0 ? (
        <div className="text-center py-20 text-[color:var(--color-text-faint)]">
          <p className="text-5xl mb-4">💳</p>
          <p className="text-sm">
            {giftCards.length === 0
              ? 'No gift cards yet. Hit + to track a gift card, store credit, or prepaid balance that decreases as you spend it.'
              : 'No active cards. Toggle "Show empty/archived" to see spent ones.'}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3">
          {visible.map((g) => (
            <GiftCardTile key={g._id} card={g} onOpen={() => setEditing(g)} />
          ))}
        </div>
      )}

      <Modal open={showCreate} onClose={() => setShowCreate(false)} title="New gift card" size="lg">
        <GiftCardForm onSuccess={() => setShowCreate(false)} />
      </Modal>
      {editing && (
        <Modal open onClose={() => setEditing(null)} title={editing.title} size="lg">
          <GiftCardForm card={editing} onSuccess={() => setEditing(null)} onDeleted={() => setEditing(null)} />
        </Modal>
      )}
    </main>
  );
}

function GiftCardTile({ card, onOpen }: { card: SerializedGiftCard; onOpen: () => void }) {
  const balance = giftCardBalance(card.initialAmount, card.uses);
  const pct = giftCardSpentPct(card.initialAmount, card.uses);
  const empty = balance <= 0.009;
  return (
    <button
      onClick={onOpen}
      className={cn(
        'text-left p-4 rounded-xl border bg-[color:var(--color-surface)] hover:-translate-y-0.5 transition-transform',
        empty || card.archived ? 'border-[color:var(--color-border)] opacity-70' : 'border-[color:var(--color-border-light)]'
      )}
    >
      <div className="flex items-start justify-between gap-2 mb-3">
        <div className="min-w-0">
          <p className="text-[10px] uppercase tracking-[0.14em] text-[color:var(--color-text-faint)] flex items-center gap-1.5" style={{ fontFamily: 'var(--font-mono)' }}>
            <CreditCard size={11} /> {card.store || 'gift card'}
          </p>
          <p className="font-semibold text-[color:var(--color-text)] truncate mt-0.5">{card.title}</p>
        </div>
        {card.archived ? (
          <span className="text-[10px] px-1.5 py-0.5 rounded bg-[color:var(--color-surface-2)] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
            archived
          </span>
        ) : (
          <ExpiryBadge expiresAt={card.expiresAt} />
        )}
      </div>
      <div className="flex items-baseline gap-2">
        <span className={cn('text-2xl font-bold', empty ? 'text-[color:var(--color-text-faint)]' : 'text-[color:var(--color-accent)]')} style={{ fontFamily: 'var(--font-display)' }}>
          {money(Math.max(0, balance))}
        </span>
        {card.initialAmount > 0 && <span className="text-xs text-[color:var(--color-text-faint)]">of {money(card.initialAmount)}</span>}
      </div>
      <div className="mt-2 h-1.5 rounded-full bg-[color:var(--color-surface-2)] overflow-hidden">
        <div className="h-full rounded-full bg-[color:var(--color-accent)]" style={{ width: `${100 - pct}%` }} />
      </div>
    </button>
  );
}

function GiftCardForm({ card, onSuccess, onDeleted }: { card?: SerializedGiftCard; onSuccess: () => void; onDeleted?: () => void }) {
  const locale = useLocale();
  const [pending, startTransition] = useTransition();
  const confirm = useConfirm();
  const [error, setError] = useState('');
  // Quick-spend row
  const [spendAmt, setSpendAmt] = useState('');
  const [spendNote, setSpendNote] = useState('');
  const [spendErr, setSpendErr] = useState('');

  const balance = card ? giftCardBalance(card.initialAmount, card.uses) : 0;

  const submit = (formData: FormData) => {
    setError('');
    startTransition(async () => {
      try {
        if (card) await updateGiftCard(card._id, formData);
        else await createGiftCard(formData);
        onSuccess();
      } catch (e) {
        setError((e as Error).message || 'Save failed');
      }
    });
  };

  const spend = (sign: 1 | -1) => {
    const amt = Number(spendAmt) * sign;
    setSpendErr('');
    startTransition(async () => {
      const r = await addGiftCardUse(card!._id, amt, spendNote);
      if (!r.ok) setSpendErr(r.error || 'Failed');
      else {
        setSpendAmt('');
        setSpendNote('');
      }
    });
  };

  const label = 'block text-[11px] uppercase tracking-[0.1em] text-[color:var(--color-text-faint)] mb-1';

  return (
    <div className="space-y-5">
      <form action={submit} className="grid grid-cols-1 md:grid-cols-2 gap-3">
        <div className="md:col-span-2">
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Title</label>
          <Input name="title" defaultValue={card?.title} placeholder="IKEA gift card" required />
        </div>
        <div>
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Store</label>
          <Input name="store" defaultValue={card?.store} placeholder="IKEA" />
        </div>
        <div>
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Face value ({cur()})</label>
          <Input name="initialAmount" type="number" step="0.01" min="0" defaultValue={card?.initialAmount || ''} placeholder="50" />
        </div>
        <div>
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Code / card number</label>
          <Input name="code" defaultValue={card?.code} placeholder="optional" />
        </div>
        <div>
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Expires</label>
          <Input name="expiresAt" type="date" defaultValue={card?.expiresAt ? card.expiresAt.slice(0, 10) : ''} />
        </div>
        <div className="md:col-span-2">
          <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Notes</label>
          <Input name="notes" defaultValue={card?.notes} placeholder="optional" />
        </div>
        {error && <p className="md:col-span-2 text-xs text-[color:var(--color-red)]">{error}</p>}
        <div className="md:col-span-2 flex items-center justify-between gap-2">
          <Button type="submit" variant="primary" disabled={pending}>
            {card ? 'Save' : 'Add card'}
          </Button>
          {card && onDeleted && (
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() =>
                  startTransition(async () => {
                    await setGiftCardArchived(card._id, !card.archived);
                    onDeleted();
                  })
                }
                className="text-xs px-2 py-1.5 rounded-lg text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] flex items-center gap-1"
                style={{ fontFamily: 'var(--font-mono)' }}
              >
                {card.archived ? <ArchiveRestore size={13} /> : <Archive size={13} />} {card.archived ? 'Reopen' : 'Archive'}
              </button>
              <button
                type="button"
                onClick={async () => {
                  const ok = await confirm({ title: 'Delete gift card', message: `Delete "${card.title}"? It moves to Trash.`, confirmLabel: 'Delete', danger: true });
                  if (ok) startTransition(async () => { await deleteGiftCard(card._id); onDeleted(); });
                }}
                className="text-xs px-2 py-1.5 rounded-lg text-[color:var(--color-red)] hover:bg-[color:var(--color-red)]/10 flex items-center gap-1"
                style={{ fontFamily: 'var(--font-mono)' }}
              >
                <Trash2 size={13} /> Delete
              </button>
            </div>
          )}
        </div>
      </form>

      {card && (
        <div className="pt-4 border-t border-[color:var(--color-border)] space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-[11px] uppercase tracking-[0.1em] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
              Balance
            </p>
            <p className="text-lg font-bold text-[color:var(--color-accent)]" style={{ fontFamily: 'var(--font-display)' }}>
              {money(balance)}
            </p>
          </div>

          {/* Quick spend / reload */}
          <div className="flex items-end gap-2 flex-wrap">
            <div className="flex-1 min-w-[110px]">
              <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Amount ({cur()})</label>
              <Input type="number" step="0.01" min="0" value={spendAmt} onChange={(e) => setSpendAmt(e.target.value)} placeholder="0.00" />
            </div>
            <div className="flex-1 min-w-[110px]">
              <label className={label} style={{ fontFamily: 'var(--font-mono)' }}>Note</label>
              <Input value={spendNote} onChange={(e) => setSpendNote(e.target.value)} placeholder="optional" />
            </div>
            <Button type="button" variant="ghost" disabled={pending || !spendAmt} onClick={() => spend(1)}>
              <Minus size={14} /> Spend
            </Button>
            <Button type="button" variant="ghost" disabled={pending || !spendAmt} onClick={() => spend(-1)}>
              <Plus size={14} /> Reload
            </Button>
          </div>
          {spendErr && <p className="text-xs text-[color:var(--color-red)]">{spendErr}</p>}

          {card.uses.length > 0 && (
            <ul className="space-y-1 max-h-52 overflow-y-auto">
              {[...card.uses]
                .sort((a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime())
                .map((u) => (
                  <li key={u._id} className="flex items-center justify-between gap-2 text-sm py-1 border-b border-[color:var(--color-border)]/50">
                    <div className="min-w-0">
                      <span className={cn('font-semibold', u.amount >= 0 ? 'text-[color:var(--color-text)]' : 'text-[color:var(--color-accent)]')}>
                        {u.amount >= 0 ? '−' : '+'}
                        {money(Math.abs(u.amount))}
                      </span>
                      {u.note && <span className="ml-2 text-[color:var(--color-text-faint)] truncate">{u.note}</span>}
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      <span className="text-[11px] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
                        {formatDate(u.date, locale)}
                      </span>
                      <button
                        type="button"
                        onClick={() => startTransition(async () => { await removeGiftCardUse(card._id, u._id); })}
                        className="text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)]"
                        title="Remove entry"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  </li>
                ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

'use client';
import { useState, useTransition, useMemo, useRef } from 'react';
import { Plus, Pencil, Trash2, ExternalLink, Copy, Check, Ticket, Search, LayoutGrid, List as ListIcon, SlidersHorizontal, Sparkles, Upload, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { SearchableSelect } from '@/components/ui/SearchableSelect';
import { useConfirm } from '@/components/ui/ConfirmDialog';
import { useOpenParam } from '@/components/useOpenParam';
import { cn } from '@/components/ui/cn';
import { shrinkImage } from '@/lib/clientImage';
import type { SerializedVoucher } from '@/types';
import { useT } from '@/components/LocaleProvider';
import type { TKey } from '@/lib/i18n';
import { createVoucher, updateVoucher, deleteVoucher, toggleVoucherUsed, scanVoucherText, scanVoucherImage } from './actions';
import { compareNames } from '@/lib/i18n/format';
import { useLocale } from '@/components/LocaleProvider';

const FILTERS = [
  { label: 'All', value: 'all' },
  { label: 'Active', value: 'active' },
  { label: 'Used', value: 'used' },
];

function daysUntil(dateStr: string | null): number | null {
  if (!dateStr) return null;
  return Math.ceil((new Date(dateStr).getTime() - Date.now()) / 86400000);
}

export function VouchersClient({ vouchers }: { vouchers: SerializedVoucher[] }) {
  const locale = useLocale();
  const t = useT();
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [storeFilter, setStoreFilter] = useState('');
  const [sortBy, setSortBy] = useState<'expiry' | 'store' | 'title'>('expiry');
  const [layout, setLayout] = useState<'grid' | 'list'>('grid');
  const [showFilters, setShowFilters] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing] = useState<SerializedVoucher | null>(null);

  // Deep-link from global search: /vouchers?open=<id>
  useOpenParam((id) => {
    const v = vouchers.find((x) => x._id === id);
    if (v) setEditing(v);
  });

  const stores = useMemo(() => [...new Set(vouchers.map((v) => v.store).filter(Boolean))].sort(), [vouchers]);

  const visible = useMemo(() => {
    const q = search.trim().toLowerCase();
    const out = vouchers.filter((v) => {
      if (filter === 'active' && v.used) return false;
      if (filter === 'used' && !v.used) return false;
      if (storeFilter && v.store !== storeFilter) return false;
      if (q && !`${v.title} ${v.store} ${v.code} ${v.notes}`.toLowerCase().includes(q)) return false;
      return true;
    });
    return [...out].sort((a, b) => {
      if (a.used !== b.used) return a.used ? 1 : -1; // active first
      switch (sortBy) {
        case 'store':
          return compareNames(a.store, b.store, locale);
        case 'title':
          return compareNames(a.title, b.title, locale);
        default:
          return (daysUntil(a.expiresAt) ?? 99999) - (daysUntil(b.expiresAt) ?? 99999);
      }
    });
  }, [vouchers, filter, search, storeFilter, sortBy]);

  const anyF = !!(filter !== 'all' || search || storeFilter || sortBy !== 'expiry');
  const fLabel = 'text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-[0.12em] mb-1.5';
  const selCls =
    'w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg px-3 py-1.5 text-xs text-[color:var(--color-text-dim)] focus:outline-none focus:border-[color:var(--color-accent)]';
  const filterControls = (
    <div className="space-y-4">
      <Input icon={<Search size={14} />} placeholder={t('v.searchPlaceholder')} value={search} onChange={(e) => setSearch(e.target.value)} />
      <div>
        <p className={fLabel} style={{ fontFamily: 'var(--font-mono)' }}>Status</p>
        <div className="flex flex-col gap-1">
          {FILTERS.map((f) => (
            <button
              key={f.value}
              onClick={() => setFilter(f.value)}
              className={cn(
                'text-left px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
                filter === f.value ? 'bg-[color:var(--color-accent)] text-black' : 'text-[color:var(--color-text-dim)] hover:bg-[color:var(--color-surface-2)] hover:text-[color:var(--color-text)]'
              )}
              style={{ fontFamily: 'var(--font-mono)' }}
            >
              {f.value === 'all' ? t('common.all') : f.value === 'active' ? t('v.fActive') : t('v.fUsed')}
            </button>
          ))}
        </div>
      </div>
      {stores.length > 1 && (
        <div>
          <p className={fLabel} style={{ fontFamily: 'var(--font-mono)' }}>Store</p>
          <SearchableSelect value={storeFilter} onChange={setStoreFilter} options={stores} placeholder="All stores" clearable size="sm" className="w-full" />
        </div>
      )}
      <div>
        <p className={fLabel} style={{ fontFamily: 'var(--font-mono)' }}>Sort</p>
        <select value={sortBy} onChange={(e) => setSortBy(e.target.value as typeof sortBy)} className={selCls} style={{ fontFamily: 'var(--font-mono)' }}>
          <option value="expiry">{t('v.sortExpiry')}</option>
          <option value="store">{t('v.sortStore')}</option>
          <option value="title">{t('v.sortTitle')}</option>
        </select>
      </div>
      {anyF && (
        <button
          onClick={() => { setFilter('all'); setSearch(''); setStoreFilter(''); setSortBy('expiry'); }}
          className="text-[0.65rem] text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] underline"
          style={{ fontFamily: 'var(--font-mono)' }}
        >
          reset filters
        </button>
      )}
    </div>
  );

  return (
    <main className="max-w-[1400px] mx-auto px-4 py-6 pb-24">
      <div className="mb-5 flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold" style={{ fontFamily: 'var(--font-display)' }}>
            {t('nav.vouchers')}
            <span className="ml-3 text-sm font-normal text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
              {t('v.activeCount', { n: vouchers.filter((v) => !v.used).length })}
            </span>
          </h1>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg p-0.5">
            {([['grid', <LayoutGrid key="g" size={14} />], ['list', <ListIcon key="l" size={14} />]] as const).map(([v, icon]) => (
              <button
                key={v}
                onClick={() => setLayout(v)}
                title={v === 'grid' ? t('v.grid') : t('v.list')}
                className={cn('px-2 py-1.5 rounded-md transition-colors', layout === v ? 'bg-[color:var(--color-accent)] text-black' : 'text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)]')}
              >
                {icon}
              </button>
            ))}
          </div>
          <Button variant="primary" onClick={() => setShowCreate(true)}>
            <Plus size={16} strokeWidth={2.5} /> {t('v.newVoucher')}
          </Button>
        </div>
      </div>

      {/* E-shop body: filter sidebar + vouchers */}
      <div className="flex gap-6 items-start">
        <aside className="hidden lg:block w-56 shrink-0 sticky top-4 self-start">{filterControls}</aside>

        <div className="flex-1 min-w-0">
          {/* Mobile filter toggle + drawer */}
          <div className="lg:hidden mb-4">
            <button
              onClick={() => setShowFilters((v) => !v)}
              className="flex items-center gap-1.5 text-xs px-3 py-2 rounded-lg bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] text-[color:var(--color-text-dim)]"
              style={{ fontFamily: 'var(--font-mono)' }}
            >
              <SlidersHorizontal size={14} /> Filters {anyF && <span className="text-[color:var(--color-accent)]">•</span>}
            </button>
            {showFilters && <div className="mt-3 p-3 rounded-xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)]">{filterControls}</div>}
          </div>

          {visible.length === 0 ? (
            <div className="text-center py-20 text-[color:var(--color-text-faint)]">
              <p className="text-5xl mb-4">🎟️</p>
              <p className="text-sm">{vouchers.length === 0 ? 'No vouchers here. Hit + to save a coupon or promo code.' : 'No vouchers match these filters.'}</p>
            </div>
          ) : (
            <div className={cn(layout === 'grid' ? 'grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3' : 'flex flex-col gap-2')}>
              {visible.map((v) => (
                <VoucherCard key={v._id} voucher={v} onEdit={() => setEditing(v)} />
              ))}
            </div>
          )}
        </div>
      </div>

      <Modal open={showCreate} onClose={() => setShowCreate(false)} title={t('v.newVoucher')} size="xl">
        <VoucherForm onSuccess={() => setShowCreate(false)} />
      </Modal>
      {editing && (
        <Modal open onClose={() => setEditing(null)} title={editing.title} size="xl">
          <VoucherForm voucher={editing} onSuccess={() => setEditing(null)} onDeleted={() => setEditing(null)} />
        </Modal>
      )}
    </main>
  );
}

function VoucherCard({ voucher, onEdit }: { voucher: SerializedVoucher; onEdit: () => void }) {
  const t = useT();
  const [pending, startTransition] = useTransition();
  const [copied, setCopied] = useState(false);
  const confirm = useConfirm();
  const d = daysUntil(voucher.expiresAt);
  const expired = d !== null && d < 0;

  function copy() {
    if (!voucher.code) return;
    navigator.clipboard?.writeText(voucher.code);
    setCopied(true);
    setTimeout(() => setCopied(false), 1200);
  }

  async function handleDelete() {
    const ok = await confirm({ title: t('v.deleteVoucher'), message: t('v.confirmDelete', { title: voucher.title }), confirmLabel: t('common.delete'), danger: true });
    if (ok) startTransition(() => deleteVoucher(voucher._id));
  }

  return (
    <div className={cn('group bg-[color:var(--color-surface)] border border-[color:var(--color-border)] rounded-2xl p-4 transition-all', voucher.used && 'opacity-50')}>
      <div className="flex items-start justify-between gap-2 mb-2">
        <div className="min-w-0">
          <h3 className="font-semibold text-sm leading-snug" style={{ fontFamily: 'var(--font-display)' }}>
            {voucher.title}
          </h3>
          {voucher.store && <p className="text-xs text-[color:var(--color-text-faint)] truncate">{voucher.store}</p>}
        </div>
        {voucher.discount && (
          <span className="shrink-0 text-xs font-bold px-2 py-0.5 rounded-md bg-[#00ff8820] text-[color:var(--color-accent)] border border-[#00ff8840]" style={{ fontFamily: 'var(--font-mono)' }}>
            {voucher.discount}
          </span>
        )}
      </div>

      {voucher.code && (
        <button
          onClick={copy}
          className="w-full flex items-center justify-between gap-2 bg-[color:var(--color-surface-2)] border border-dashed border-[color:var(--color-border-light)] rounded-lg px-3 py-2 mb-2 hover:border-[color:var(--color-accent)] transition-colors"
        >
          <span className="text-sm font-bold tracking-wider truncate" style={{ fontFamily: 'var(--font-mono)' }}>
            {voucher.code}
          </span>
          {copied ? <Check size={14} className="text-[color:var(--color-accent)] shrink-0" /> : <Copy size={13} className="text-[color:var(--color-text-faint)] shrink-0" />}
        </button>
      )}

      <div className="flex items-center gap-2 text-[10px] mb-3" style={{ fontFamily: 'var(--font-mono)' }}>
        {voucher.expiresAt ? (
          <span className={cn(expired ? 'text-[color:var(--color-red)]' : d! <= 7 ? 'text-[color:var(--color-gold)]' : 'text-[color:var(--color-text-faint)]')}>
            {expired ? t('v.expired') : t('v.expiresInD', { d: d ?? 0 })}
          </span>
        ) : (
          <span className="text-[color:var(--color-text-faint)]">{t('v.noExpiry')}</span>
        )}
        {voucher.used && <span className="text-[color:var(--color-text-faint)]">· {t('v.usedTag')}</span>}
      </div>

      <div className="flex items-center gap-1 pt-2 border-t border-[color:var(--color-border)]">
        <button
          onClick={() => startTransition(() => toggleVoucherUsed(voucher._id, !voucher.used))}
          disabled={pending}
          className={cn('flex items-center gap-1 text-[10px] px-2 py-1 rounded-md transition-colors', voucher.used ? 'text-[color:var(--color-text-faint)] hover:text-[color:var(--color-accent)]' : 'text-[color:var(--color-accent)] hover:bg-[color:var(--color-surface-2)]')}
        >
          <Check size={12} /> {voucher.used ? t('v.markUnused') : t('v.markUsed')}
        </button>
        <button onClick={onEdit} className="p-1.5 rounded-md text-[color:var(--color-text-faint)] hover:text-[color:var(--color-text)] hover:bg-[color:var(--color-surface-2)]" aria-label="Edit">
          <Pencil size={13} />
        </button>
        {voucher.url && (
          <a href={voucher.url} target="_blank" rel="noopener noreferrer" className="p-1.5 rounded-md text-[color:var(--color-text-faint)] hover:text-[color:var(--color-cyan)] hover:bg-[color:var(--color-surface-2)]" aria-label="Open">
            <ExternalLink size={13} />
          </a>
        )}
        <button onClick={handleDelete} disabled={pending} className="ml-auto p-1.5 rounded-md text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 transition-all" aria-label="Delete">
          <Trash2 size={13} />
        </button>
      </div>
    </div>
  );
}

function VoucherForm({ voucher, onSuccess, onDeleted }: { voucher?: SerializedVoucher; onSuccess: () => void; onDeleted?: () => void }) {
  const t = useT();
  const [pending, startTransition] = useTransition();
  const confirm = useConfirm();
  const [error, setError] = useState('');
  const [form, setForm] = useState({
    title: voucher?.title ?? '',
    code: voucher?.code ?? '',
    store: voucher?.store ?? '',
    discount: voucher?.discount ?? '',
    expiresAt: voucher?.expiresAt ? voucher.expiresAt.slice(0, 10) : '',
    url: voucher?.url ?? '',
    notes: voucher?.notes ?? '',
  });

  async function handleDelete() {
    if (!voucher) return;
    const ok = await confirm({ title: t('v.deleteVoucher'), message: t('v.confirmDelete', { title: voucher.title }), confirmLabel: t('common.delete'), danger: true });
    if (ok) startTransition(async () => { await deleteVoucher(voucher._id); onDeleted?.(); });
  }
  const set = (k: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
    setForm((p) => ({ ...p, [k]: e.target.value }));

  // ── AI scan: paste text or upload a coupon image → prefill the form ──
  const [aiText, setAiText] = useState('');
  const [aiMsg, setAiMsg] = useState<string | null>(null);
  const aiFileRef = useRef<HTMLInputElement>(null);

  function applyParsed(d: { title: string; code: string; store: string; discount: string; expiresAt: string; url: string; notes: string }) {
    setForm((p) => ({
      title: d.title || p.title,
      code: d.code || p.code,
      store: d.store || p.store,
      discount: d.discount || p.discount,
      expiresAt: /^\d{4}-\d{2}-\d{2}/.test(d.expiresAt) ? d.expiresAt.slice(0, 10) : p.expiresAt,
      url: d.url || p.url,
      notes: d.notes || p.notes,
    }));
    setAiMsg('Filled from AI ✓ — review & save');
  }
  function scanText() {
    setAiMsg('Reading…');
    startTransition(async () => {
      const r = await scanVoucherText(aiText);
      if (r.ok) applyParsed(r.data);
      else setAiMsg(r.error);
    });
  }
  function scanImage(file: File | undefined) {
    if (!file) return;
    setAiMsg('Reading image…');
    startTransition(async () => {
      let f = file;
      try {
        f = await shrinkImage(file);
      } catch {
        /* use original */
      }
      const fd = new FormData();
      fd.set('file', f);
      const r = await scanVoucherImage(fd);
      if (r.ok) applyParsed(r.data);
      else setAiMsg(r.error);
    });
  }

  function submit(e: React.FormEvent) {
    e.preventDefault();
    setError('');
    const fd = new FormData();
    Object.entries(form).forEach(([k, v]) => fd.set(k, v));
    startTransition(async () => {
      try {
        if (voucher) await updateVoucher(voucher._id, fd);
        else await createVoucher(fd);
        onSuccess();
      } catch (err) {
        setError((err as Error).message || 'Save failed');
      }
    });
  }

  return (
    <form onSubmit={submit} className="space-y-3">
      {!voucher && (
        <div className="rounded-xl border border-[color:var(--color-border)] bg-[color:var(--color-surface-2)] p-3 space-y-2">
          <p className="text-[10px] uppercase tracking-wider text-[color:var(--color-cyan)] flex items-center gap-1.5" style={{ fontFamily: 'var(--font-mono)' }}>
            <Sparkles size={12} /> {t('v.fillAi')}
          </p>
          <textarea
            value={aiText}
            onChange={(e) => setAiText(e.target.value)}
            rows={2}
            placeholder={t('v.aiPlaceholder')}
            className="w-full bg-[color:var(--color-surface-3)] border border-[color:var(--color-border)] rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-[color:var(--color-accent)]"
          />
          <div className="flex items-center gap-2 flex-wrap">
            <button type="button" onClick={scanText} disabled={pending || !aiText.trim()} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg bg-[color:var(--color-accent)] text-black font-semibold disabled:opacity-50">
              {pending ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />} {t('v.scanText')}
            </button>
            <button type="button" onClick={() => aiFileRef.current?.click()} disabled={pending} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg bg-[color:var(--color-surface-3)] border border-[color:var(--color-border)] hover:border-[color:var(--color-cyan)] disabled:opacity-50">
              <Upload size={13} /> {t('v.scanImage')}
            </button>
            <input ref={aiFileRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={(e) => scanImage(e.target.files?.[0])} />
            {aiMsg && <span className="text-[11px] text-[color:var(--color-text-dim)]" style={{ fontFamily: 'var(--font-mono)' }}>{aiMsg}</span>}
          </div>
        </div>
      )}
      <Field label={t('v.fTitle')}>
        <Input value={form.title} onChange={set('title')} required placeholder={t('v.fTitlePlaceholder')} />
      </Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label={t('v.fCode')}>
          <Input value={form.code} onChange={set('code')} placeholder="SAVE10" style={{ fontFamily: 'var(--font-mono)' }} />
        </Field>
        <Field label={t('v.fDiscount')}>
          <Input value={form.discount} onChange={set('discount')} placeholder={t('v.fDiscountPlaceholder')} />
        </Field>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Field label={t('v.fStore')}>
          <Input value={form.store} onChange={set('store')} placeholder={t('v.fStorePlaceholder')} />
        </Field>
        <Field label={t('v.fExpires')}>
          <Input type="date" value={form.expiresAt} onChange={set('expiresAt')} />
        </Field>
      </div>
      <Field label="URL">
        <Input value={form.url} onChange={set('url')} placeholder="https://..." />
      </Field>
      <Field label={t('v.fNotes')}>
        <textarea
          value={form.notes}
          onChange={set('notes')}
          rows={2}
          className="w-full bg-[color:var(--color-surface-2)] border border-[color:var(--color-border)] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[color:var(--color-accent)] resize-none"
        />
      </Field>
      {error && <p className="text-xs text-[color:var(--color-red)]">{error}</p>}
      <div className="flex gap-3 pt-2">
        <Button type="submit" variant="primary" disabled={pending}>
          {pending ? t('v.saving') : voucher ? t('common.save') : t('v.create')}
        </Button>
        {voucher && onDeleted && (
          <Button type="button" variant="danger" size="sm" className="ml-auto" onClick={handleDelete} disabled={pending}>
            <Trash2 size={13} /> {t('common.delete')}
          </Button>
        )}
      </div>
    </form>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="min-w-0">
      <label className="block text-[10px] text-[color:var(--color-text-faint)] uppercase tracking-wider mb-1.5" style={{ fontFamily: 'var(--font-mono)' }}>
        {label}
      </label>
      {children}
    </div>
  );
}

'use client';
import { useState } from 'react';
import { useSearchParams } from 'next/navigation';
import { Ticket, CreditCard, Barcode } from 'lucide-react';
import { cn } from '@/components/ui/cn';
import { VouchersClient } from './VouchersClient';
import { GiftCardsClient } from './GiftCardsClient';
import { LoyaltyCardsClient } from './LoyaltyCardsClient';
import { giftCardBalance } from '@/lib/giftcard';
import type { SerializedVoucher, SerializedGiftCard, SerializedLoyaltyCard } from '@/types';

// P32/P20 — thin tab wrapper: Coupons (existing vouchers) | Gift cards (balance
// tracker) | Loyalty cards (barcode wallet). Each tab renders its own <main>
// with its own header/filters below.
type Tab = 'coupons' | 'giftcards' | 'loyalty';

export function VouchersShell({
  vouchers,
  giftCards,
  loyaltyCards,
}: {
  vouchers: SerializedVoucher[];
  giftCards: SerializedGiftCard[];
  loyaltyCards: SerializedLoyaltyCard[];
}) {
  // Global search deep-links a gift/loyalty card as ?tab=<id>&open=<id> (P66). Read the tab
  // ONCE into state rather than deriving it every render: the child's useOpenParam strips the
  // query string after opening the detail, which would otherwise snap the tab back to coupons.
  const initialTab = useSearchParams().get('tab');
  const [tab, setTab] = useState<Tab>(initialTab === 'giftcards' || initialTab === 'loyalty' ? initialTab : 'coupons');
  const liveCards = giftCards.filter((g) => !g.archived && giftCardBalance(g.initialAmount, g.uses) > 0.009).length;
  const activeVouchers = vouchers.filter((v) => !v.used).length;
  const activeLoyalty = loyaltyCards.filter((c) => !c.archived).length;

  const TabButton = ({ id, icon, label, count }: { id: Tab; icon: React.ReactNode; label: string; count: number }) => (
    <button
      onClick={() => setTab(id)}
      className={cn(
        'flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold transition-colors',
        tab === id ? 'bg-[color:var(--color-accent)] text-black' : 'text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] hover:bg-[color:var(--color-surface-2)]'
      )}
      style={{ fontFamily: 'var(--font-mono)' }}
    >
      {icon} {label}
      {count > 0 && (
        <span className={cn('text-[10px] px-1.5 py-0.5 rounded-full', tab === id ? 'bg-black/20' : 'bg-[color:var(--color-surface-2)]')}>{count}</span>
      )}
    </button>
  );

  return (
    <>
      <div className="max-w-[1400px] mx-auto px-4 pt-6">
        <div className="flex gap-2">
          <TabButton id="coupons" icon={<Ticket size={15} />} label="Coupons" count={activeVouchers} />
          <TabButton id="giftcards" icon={<CreditCard size={15} />} label="Gift cards" count={liveCards} />
          <TabButton id="loyalty" icon={<Barcode size={15} />} label="Loyalty cards" count={activeLoyalty} />
        </div>
      </div>
      {tab === 'coupons' ? <VouchersClient vouchers={vouchers} /> : tab === 'giftcards' ? <GiftCardsClient giftCards={giftCards} /> : <LoyaltyCardsClient cards={loyaltyCards} />}
    </>
  );
}

