'use client';
import { useState, useRef, useEffect, useCallback, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { Bell, Tag, ShieldCheck, CreditCard, TrendingUp, AlarmClock, Wallet, FileText, Wrench, Handshake, PackageOpen, IdCard, Cake, X } from 'lucide-react';
import { cn } from '@/components/ui/cn';
import { cur } from '@/lib/money';
import { useT } from '@/components/LocaleProvider';
import { relTime } from '@/lib/i18n/format';
import {
  getNotifications,
  markNotificationRead,
  markAllNotificationsRead,
  dismissNotification,
  clearAllNotifications,
  type SerializedNotification,
  type NotifKind,
} from '@/app/notifications/actions';

const KIND_ICON: Record<NotifKind, typeof Bell> = { deal: Tag, warranty: ShieldCheck, installment: CreditCard, pricehike: TrendingUp, trialend: AlarmClock, subreview: AlarmClock, giftcard: Wallet, bill: FileText, maintenance: Wrench, lending: Handshake, claim: PackageOpen, document: IdCard, specialdate: Cake, system: Bell };
const KIND_COLOR: Record<NotifKind, string> = {
  deal: 'var(--color-accent)',
  warranty: 'var(--color-gold)',
  installment: 'var(--color-cyan)',
  pricehike: 'var(--color-red)',
  trialend: 'var(--color-purple)',
  subreview: 'var(--color-cyan)',
  giftcard: 'var(--color-cyan)',
  bill: 'var(--color-gold)',
  maintenance: 'var(--color-cyan)',
  lending: 'var(--color-purple)',
  claim: 'var(--color-orange)',
  document: 'var(--color-gold)',
  specialdate: 'var(--color-purple)',
  system: 'var(--color-text-dim)',
};

/** Navbar bell: in-app alerts (deals, warranties, installments due) with an
 *  unread badge. Polls every 60s; the server generates alerts on a throttle.
 *
 *  `open`/`onOpenChange` are controlled by SiteNav rather than local state — on mobile this
 *  dropdown and the hamburger nav menu are both `position: absolute` panels that used to open
 *  independently and visually collide (screenshotted: the notifications panel sitting on top
 *  of the product link grid). SiteNav now tracks a single "which panel is open" state and
 *  closes one when the other opens; this component just reports its own open/close intent up
 *  instead of owning the boolean itself. */
export function NotificationBell({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  const t = useT();
  const router = useRouter();
  const ref = useRef<HTMLDivElement>(null);
  const [items, setItems] = useState<SerializedNotification[]>([]);
  const [unread, setUnread] = useState(0);
  const [, start] = useTransition();

  const refresh = useCallback(async () => {
    try {
      const r = await getNotifications();
      setItems(r.items);
      setUnread(r.unread);
    } catch {
      /* a poll failure shouldn't surface in the navbar */
    }
  }, []);

  useEffect(() => {
    refresh();
    const id = setInterval(refresh, 60000);
    return () => clearInterval(id);
  }, [refresh]);

  // Only listen while this panel is actually open. `onOpenChange(false)` is SiteNav's
  // SHARED panel state ('none'), not a local boolean, so a dismiss fired while the bell is
  // closed does not close "nothing" — it closes whatever else is open. Unguarded, every
  // mousedown anywhere tore down the mobile nav menu, and since mousedown precedes click on
  // a tap, the link unmounted before the tap landed: the menu just blinked shut and never
  // navigated ("it's like not pressed, it minimizes it"). Reported on mobile, all pages.
  useEffect(() => {
    if (!open) return;
    function onDown(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) onOpenChange(false);
    }
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onOpenChange(false);
    }
    document.addEventListener('mousedown', onDown);
    window.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDown);
      window.removeEventListener('keydown', onKey);
    };
  }, [open, onOpenChange]);

  // The stored `body` is a structured payload; localize it per viewer here.
  function describe(n: SerializedNotification): { heading: string; sub: string } {
    if (n.kind === 'deal') {
      const [lo, target] = n.body.split('|');
      return { heading: n.title, sub: t('notif.dealSub', { now: cur() + lo, target: cur() + target }) };
    }
    if (n.kind === 'warranty') return { heading: n.title, sub: t('notif.warrantySub', { days: n.body }) };
    if (n.kind === 'installment') {
      const [amount, count] = n.body.split('|');
      return { heading: t('notif.installmentHeading'), sub: t('notif.installmentSub', { amount: cur() + amount, n: count }) };
    }
    if (n.kind === 'pricehike') {
      const [prev, curr, pct] = n.body.split('|');
      const p = Number(pct);
      const key = p >= 0 ? 'notif.priceHikeSub' : 'notif.priceDropSub';
      return {
        heading: n.title,
        sub: t(key, { prev: cur() + prev, curr: cur() + curr, pct: `${p > 0 ? '+' : ''}${pct}%` }),
      };
    }
    if (n.kind === 'trialend') {
      const [days, amount] = n.body.split('|');
      const key = Number(days) <= 0 ? 'notif.trialTodaySub' : 'notif.trialSub';
      return { heading: n.title, sub: t(key, { days, amount: cur() + amount }) };
    }
    if (n.kind === 'subreview') return { heading: n.title, sub: t('notif.subscriptionReviewSub', { days: n.body }) };
    if (n.kind === 'giftcard') {
      const [days, balance] = n.body.split('|');
      const key = Number(days) <= 0 ? 'notif.giftcardTodaySub' : 'notif.giftcardSub';
      return { heading: n.title, sub: t(key, { days, balance: cur() + balance }) };
    }
    if (n.kind === 'bill') {
      const [days, amount] = n.body.split('|');
      const d = Number(days);
      const key = d < 0 ? 'notif.billOverdueSub' : d === 0 ? 'notif.billTodaySub' : 'notif.billDueSub';
      return { heading: n.title, sub: t(key, { days: Math.abs(d), amount: cur() + amount }) };
    }
    if (n.kind === 'maintenance') {
      const d = Number(n.body);
      const key = d < 0 ? 'notif.maintenanceOverdueSub' : d === 0 ? 'notif.maintenanceTodaySub' : 'notif.maintenanceSub';
      return { heading: n.title, sub: t(key, { days: Math.abs(d) }) };
    }
    if (n.kind === 'lending') {
      // body = "<days>|<borrower>"; split on the first bar only, a name may contain one.
      const bar = n.body.indexOf('|');
      const d = Number(bar < 0 ? n.body : n.body.slice(0, bar));
      const name = bar < 0 ? '' : n.body.slice(bar + 1);
      const key = d < 0 ? 'notif.lendingOverdueSub' : d === 0 ? 'notif.lendingTodaySub' : 'notif.lendingSub';
      return { heading: n.title, sub: t(key, { days: Math.abs(d), name }) };
    }
    if (n.kind === 'claim') {
      // body = "<days>|<ref>"; split on the first bar only, a ticket number may contain one.
      const bar = n.body.indexOf('|');
      const days = bar < 0 ? n.body : n.body.slice(0, bar);
      const ref = bar < 0 ? '' : n.body.slice(bar + 1);
      const key = ref ? 'notif.claimStaleSub' : 'notif.claimStaleNoRefSub';
      return { heading: n.title, sub: t(key, { days, ref }) };
    }
    if (n.kind === 'document') {
      const d = Number(n.body);
      const key = d < 0 ? 'notif.documentExpiredSub' : d === 0 ? 'notif.documentTodaySub' : 'notif.documentSub';
      return { heading: n.title, sub: t(key, { days: Math.abs(d) }) };
    }
    if (n.kind === 'specialdate') {
      // body = "<days>|<years>"; years is empty when the year is unknown, and then the
      // line says nothing about age rather than guessing one.
      const [days, years] = n.body.split('|');
      const today = Number(days) === 0;
      const key = years
        ? today ? 'notif.specialDateTodayYearsSub' : 'notif.specialDateYearsSub'
        : today ? 'notif.specialDateTodaySub' : 'notif.specialDateSub';
      return { heading: n.title, sub: t(key, { days, years: years ?? '' }) };
    }
    return { heading: n.title, sub: n.body };
  }

  function openItem(n: SerializedNotification) {
    onOpenChange(false);
    if (!n.read) {
      setItems((p) => p.map((x) => (x._id === n._id ? { ...x, read: true } : x)));
      setUnread((u) => Math.max(0, u - 1));
      start(() => void markNotificationRead(n._id));
    }
    if (n.href) router.push(n.href);
  }
  function dismiss(e: React.MouseEvent, n: SerializedNotification) {
    e.stopPropagation();
    setItems((p) => p.filter((x) => x._id !== n._id));
    if (!n.read) setUnread((u) => Math.max(0, u - 1));
    start(() => void dismissNotification(n._id));
  }
  function markAll() {
    setItems((p) => p.map((x) => ({ ...x, read: true })));
    setUnread(0);
    start(() => void markAllNotificationsRead());
  }
  function clearAll() {
    setItems([]);
    setUnread(0);
    start(() => void clearAllNotifications());
  }

  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => {
          onOpenChange(!open);
          if (!open) refresh();
        }}
        className={cn(
          'relative p-2 rounded-lg transition-colors',
          open ? 'text-[color:var(--color-accent)] bg-[color:var(--color-surface)]' : 'text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] hover:bg-[color:var(--color-surface)]'
        )}
        aria-label={t('notif.title')}
        title={t('notif.title')}
      >
        <Bell size={17} />
        {unread > 0 && (
          <span
            className="absolute -top-0.5 -right-0.5 min-w-[16px] h-4 px-1 grid place-items-center rounded-full bg-[color:var(--color-accent)] text-black text-[9px] font-bold"
            style={{ fontFamily: 'var(--font-mono)' }}
          >
            {unread > 9 ? '9+' : unread}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 top-full mt-2 w-[340px] max-w-[92vw] z-50 rounded-2xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)] shadow-2xl shadow-black/40 overflow-hidden">
          <div className="flex items-center justify-between px-3 py-2 border-b border-[color:var(--color-border)]">
            <span className="text-xs font-semibold" style={{ fontFamily: 'var(--font-display)' }}>
              {t('notif.title')}
            </span>
            {items.length > 0 && (
              <div className="flex items-center gap-2.5">
                {unread > 0 && (
                  <button onClick={markAll} className="text-[10px] text-[color:var(--color-cyan)] hover:underline">
                    {t('notif.markAllRead')}
                  </button>
                )}
                <button onClick={clearAll} className="text-[10px] text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)]">
                  {t('notif.clearAll')}
                </button>
              </div>
            )}
          </div>

          <div className="max-h-[60vh] overflow-y-auto">
            {items.length === 0 ? (
              <p className="px-4 py-8 text-center text-xs text-[color:var(--color-text-faint)]">{t('notif.empty')}</p>
            ) : (
              items.map((n) => {
                const Icon = KIND_ICON[n.kind] ?? Bell;
                const { heading, sub } = describe(n);
                return (
                  <div
                    key={n._id}
                    role="button"
                    tabIndex={0}
                    onClick={() => openItem(n)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') openItem(n);
                    }}
                    className={cn(
                      'group w-full text-left flex items-start gap-2.5 px-3 py-2.5 border-b border-[color:var(--color-border)] last:border-0 cursor-pointer transition-colors hover:bg-[color:var(--color-surface-2)] outline-none focus-visible:bg-[color:var(--color-surface-2)]',
                      !n.read && 'bg-[color:var(--color-accent)]/[0.05]'
                    )}
                  >
                    {!n.read ? (
                      <span className="mt-1.5 h-1.5 w-1.5 rounded-full bg-[color:var(--color-accent)] shrink-0" />
                    ) : (
                      <span className="mt-1.5 h-1.5 w-1.5 shrink-0" />
                    )}
                    <Icon size={15} className="mt-0.5 shrink-0" style={{ color: KIND_COLOR[n.kind] }} />
                    <span className="min-w-0 flex-1">
                      {heading && <span className="block text-sm font-medium truncate">{heading}</span>}
                      <span className="block text-xs text-[color:var(--color-text-dim)] truncate">{sub}</span>
                      <span className="block text-[10px] text-[color:var(--color-text-faint)] mt-0.5" style={{ fontFamily: 'var(--font-mono)' }}>
                        {relTime(n.createdAt, t)}
                      </span>
                    </span>
                    <button
                      onClick={(e) => dismiss(e, n)}
                      className="shrink-0 mt-0.5 opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100 text-[color:var(--color-text-faint)] hover:text-[color:var(--color-red)] transition-all"
                      aria-label={t('notif.clearAll')}
                    >
                      <X size={13} />
                    </button>
                  </div>
                );
              })
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import { cur } from "@/lib/money";
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid, Legend } from 'recharts';
import type { SerializedPriceEntry } from '@/types';
import { formatDate, formatTime, formatDateTime } from '@/lib/i18n/format';
import { useLocale } from '@/components/LocaleProvider';

const tooltipStyle = {
  background: 'var(--color-surface-2)',
  border: '1px solid var(--color-border)',
  borderRadius: 10,
  fontSize: 12,
  color: 'var(--color-text)',
};

// One distinct color per store-link, cycled if there are many.
const PALETTE = [
  'var(--color-accent)',
  'var(--color-cyan)',
  'var(--color-gold)',
  'var(--color-purple)',
  'var(--color-red)',
  'var(--color-orange)',
];

const fmtDate = (t: number, locale: string) => formatDate(t, locale, { day: '2-digit', month: '2-digit', year: '2-digit' });

/** Multi-series price history: one dotted line per store-link, plotted over time.
 *  Seeded on URL import, then a dot is appended per store every scraper pass (6h). */
export function PriceHistoryChart({ history }: { history: SerializedPriceEntry[] }) {
  const locale = useLocale();
  const valid = history.filter((h) => typeof h.price === 'number' && h.price > 0);
  if (valid.length < 2) return null;

  // Distinct stores → series. Keep first-seen order so colors stay stable.
  const stores: string[] = [];
  for (const h of valid) {
    const s = h.store || 'unknown';
    if (!stores.includes(s)) stores.push(s);
  }

  // One row per check; each row carries only its own store's price, so every line
  // draws a dot exactly where a check happened (connectNulls bridges the gaps).
  const rows = valid
    .map((h) => ({ t: new Date(h.date).getTime(), store: h.store || 'unknown', price: h.price }))
    .sort((a, b) => a.t - b.t)
    .map((r) => ({ t: r.t, [r.store]: r.price }) as { t: number; [store: string]: number });

  const prices = valid.map((h) => h.price);
  const min = Math.min(...prices);
  const max = Math.max(...prices);
  const pad = Math.max(1, Math.round((max - min) * 0.15));
  const single = stores.length === 1;

  return (
    <ResponsiveContainer width="100%" height={single ? 190 : 220}>
      <LineChart data={rows} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" vertical={false} />
        <XAxis
          dataKey="t"
          type="number"
          scale="time"
          domain={['dataMin', 'dataMax']}
          tick={{ fontSize: 10, fill: '#888' }}
          axisLine={false}
          tickLine={false}
          tickFormatter={(t: number) => fmtDate(t, locale)}
        />
        <YAxis
          domain={[min - pad, max + pad]}
          tick={{ fontSize: 10, fill: '#888' }}
          axisLine={false}
          tickLine={false}
          width={44}
          tickFormatter={(v: number) => `${cur()}${v}`}
        />
        <Tooltip
          contentStyle={tooltipStyle}
          labelFormatter={(t: number) => fmtDate(t, locale)}
          formatter={(v: number, name: string) => [`${cur()}${v}`, name]}
          cursor={{ stroke: 'var(--color-border-light)' }}
        />
        {!single && <Legend wrapperStyle={{ fontSize: 11 }} iconType="plainline" />}
        {stores.map((s, i) => (
          <Line
            key={s}
            type="monotone"
            dataKey={s}
            name={s}
            stroke={PALETTE[i % PALETTE.length]}
            strokeWidth={2}
            connectNulls
            dot={{ r: 3, fill: PALETTE[i % PALETTE.length] }}
            activeDot={{ r: 5 }}
          />
        ))}
      </LineChart>
    </ResponsiveContainer>
  );
}

'use client';
import { useState, useMemo, useTransition } from 'react';
import dynamic from 'next/dynamic';
import { cur } from '@/lib/money';
import { Plus, TrendingDown, TrendingUp, Check, Loader2, ChevronDown, ExternalLink, Target, Pencil, Search, RefreshCw, ArrowDown, ArrowUp, AlertTriangle } from 'lucide-react';
import type { SerializedItem } from '@/types';
import { logItemPrice, setItemTarget, refreshItemPrices, type PriceRefresh } from '@/app/items/actions';
import { calculatePriceTrend } from '@/lib/priceTrend';
import { getBulkAiGuard } from '@/app/jobActions';
import { useConfirm } from '@/components/ui/ConfirmDialog';
import { useLocale, useT } from '@/components/LocaleProvider';
import type { TKey } from '@/lib/i18n';
import { formatDate, formatTime, formatDateTime } from '@/lib/i18n/format';

const VERDICT_KEY: Record<string, TKey> = { deal: 'pp.vDeal', dropping: 'pp.vDropping', rising: 'pp.vRising', good: 'pp.vGood', high: 'pp.vHigh' };

const PriceHistoryChart = dynamic(() => import('@/components/PriceHistoryChart').then((m) => m.PriceHistoryChart), { ssr: false });

function linkHost(url: string): string {
  try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return url; }
}

type Verdict = 'deal' | 'dropping' | 'rising' | 'good' | 'high' | 'none';

/** One coherent price picture, replacing the scattered currentPrice / link-price /
 *  lowest / trend / deal concepts with: best-now, lowest/highest ever, trend, stores. */
function priceStatus(item: SerializedItem) {
  const stores = (item.links ?? [])
    .filter((l) => l.price && l.price > 0)
    .map((l) => ({ store: l.label || linkHost(l.url), url: l.url, price: l.price as number }))
    .sort((a, b) => a.price - b.price);

  // Headline best price = the cheapest ACTUAL store link. A standalone currentPrice
  // (seeded or hand-entered, with no store behind it) must NOT undercut real store
  // prices — it only fills in when there are no priced links at all.
  let bestNow: { price: number; store: string; url?: string } | null = stores[0] ? { ...stores[0] } : null;
  if (!bestNow && item.currentPrice > 0) bestNow = { price: item.currentPrice, store: '' };

  const hist = [...(item.priceHistory ?? [])].filter((h) => h.price > 0).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  const prices = hist.map((h) => h.price);
  if (bestNow) prices.push(bestNow.price);
  const lowestEver = hist.length ? hist.reduce((lo, h) => (h.price < lo.price ? h : lo), hist[0]) : null;
  const lo = prices.length ? Math.min(...prices) : null;
  const hi = prices.length ? Math.max(...prices) : null;
  const rawTrend = calculatePriceTrend(item.priceHistory, bestNow);
  const trend = rawTrend ?? 0;

  const target = item.targetPrice && item.targetPrice > 0 ? item.targetPrice : null;

  let verdict: Verdict = 'none';
  if (bestNow && lo != null && hi != null) {
    const range = hi - lo || 1;
    const pos = (bestNow.price - lo) / range; // 0 = cheapest seen, 1 = priciest
    if (target && bestNow.price <= target) verdict = 'deal';
    else if (trend < 0) verdict = 'dropping';
    else if (trend > 0) verdict = 'rising';
    else if (pos <= 0.15) verdict = 'good';
    else if (pos >= 0.7) verdict = 'high';
  }

  return { bestNow, lowestEver, lo, hi, target, trend, verdict, hist, stores };
}

const VERDICT_META: Record<Verdict, { label: string; cls: string; icon?: typeof TrendingDown }> = {
  deal: { label: 'Deal · at/below target', cls: 'text-[color:var(--color-accent)] bg-[color:var(--color-accent)]/12' },
  dropping: { label: 'Dropping', cls: 'text-[color:var(--color-accent)] bg-[color:var(--color-accent)]/12', icon: TrendingDown },
  rising: { label: 'Rising · maybe wait', cls: 'text-[color:var(--color-gold)] bg-[color:var(--color-gold)]/12', icon: TrendingUp },
  good: { label: 'Good price', cls: 'text-[color:var(--color-cyan)] bg-[color:var(--color-cyan)]/12' },
  high: { label: 'Above usual', cls: 'text-[color:var(--color-gold)] bg-[color:var(--color-gold)]/12' },
  none: { label: '', cls: '' },
};

const money = (n: number) => `${cur()}${Math.round(n * 100) / 100}`;

export function PricePanel({ item, summary = true, onChanged, onSearchOnline }: { item: SerializedItem; summary?: boolean; onChanged?: () => void; onSearchOnline?: () => void }) {
  const locale = useLocale();
  const s = useMemo(() => priceStatus(item), [item]);
  const t = useT();
  const [pending, startTransition] = useTransition();
  const [logging, setLogging] = useState(false);
  const [editTarget, setEditTarget] = useState(false);
  const [showFull, setShowFull] = useState(false);
  const [price, setPrice] = useState('');
  const [store, setStore] = useState('');
  const [targetVal, setTargetVal] = useState(s.target ? String(s.target) : '');
  const sortedHist = useMemo(() => [...(item.priceHistory ?? [])].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()), [item.priceHistory]);

  const storeNames = useMemo(() => [...new Set((item.links ?? []).map((l) => l.label).filter(Boolean))], [item.links]);
  const v = VERDICT_META[s.verdict];
  const toGo = s.target && s.bestNow ? s.bestNow.price - s.target : null;
  const hasRange = s.lo != null && s.hi != null && s.hi > s.lo;

  function submitPrice() {
    const p = Number(price);
    if (!(p > 0)) return;
    startTransition(async () => {
      const r = await logItemPrice(item._id, p, store);
      if (r.ok) { setPrice(''); setStore(''); setLogging(false); onChanged?.(); }
    });
  }
  function saveTarget() {
    const tv = Number(targetVal);
    startTransition(async () => {
      await setItemTarget(item._id, tv > 0 ? tv : null);
      setEditTarget(false);
      onChanged?.();
    });
  }

  const confirm = useConfirm();
  const [refreshing, setRefreshing] = useState(false);
  const [refreshResults, setRefreshResults] = useState<PriceRefresh[] | null>(null);
  const linkCount = useMemo(() => (item.links ?? []).filter((l) => l.url && /^https?:\/\//i.test(l.url)).length, [item.links]);

  // Re-check the item's ALREADY-tracked store links right now + show the diff.
  async function runRefresh() {
    const g = await getBulkAiGuard();
    if (g.confirm) {
      const ok = await confirm({
        title: t('pp.confirmRefresh'),
        message:
          g.provider === 'anthropic'
            ? t('pp.confirmRefreshCloud', { n: linkCount, model: g.model })
            : t('pp.confirmRefreshLocal', { n: linkCount, model: g.model }),
        confirmLabel: t('pp.refresh'),
      });
      if (!ok) return;
    }
    setRefreshing(true);
    setRefreshResults(null);
    const r = await refreshItemPrices(item._id);
    setRefreshing(false);
    if (!r.ok) {
      setRefreshResults([{ store: '', url: '', oldPrice: null, newPrice: null, changed: 'error', error: r.error }]);
      return;
    }
    setRefreshResults(r.results);
    onChanged?.();
  }

  return (
    <div className="rounded-2xl border border-[color:var(--color-border)] bg-[color:var(--color-surface)] p-4">
      <div className="flex items-center justify-between gap-3 mb-3">
        <span className="text-[10px] uppercase tracking-[0.15em] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
          {summary ? t('pp.price') : t('pp.priceHistory')}
        </span>
        {summary && v.label && (
          <span className={`inline-flex items-center gap-1.5 text-[11px] font-semibold px-2.5 py-1 rounded-full ${v.cls}`} style={{ fontFamily: 'var(--font-mono)' }}>
            {v.icon && <v.icon size={12} />}{t(VERDICT_KEY[s.verdict] ?? 'pp.vGood')}
          </span>
        )}
      </div>

      {summary && (
        <>
          {/* Hero: the one number that matters + trend */}
          <div className="flex items-end justify-between gap-3 flex-wrap">
            <div className="flex items-end gap-2.5">
              <span className="text-3xl font-bold leading-none" style={{ fontFamily: 'var(--font-display)' }}>
                {s.bestNow ? money(s.bestNow.price) : '—'}
              </span>
              {s.bestNow?.store && (
                <span className="text-xs text-[color:var(--color-text-dim)] pb-0.5">{t('it.at')} {s.bestNow.store}</span>
              )}
            </div>
            {s.trend !== 0 && (
              <span className={`inline-flex items-center gap-1 text-xs font-semibold ${s.trend < 0 ? 'text-[color:var(--color-accent)]' : 'text-[color:var(--color-gold)]'}`} style={{ fontFamily: 'var(--font-mono)' }}>
                {s.trend < 0 ? <TrendingDown size={13} /> : <TrendingUp size={13} />}
                {s.trend < 0 ? t('pp.down') : t('pp.up')} {money(Math.abs(s.trend))}
              </span>
            )}
          </div>

          {/* Position bar: where the current price sits between cheapest & priciest seen */}
          {hasRange && s.bestNow && (
            <div className="mt-3">
              <div className="relative h-1.5 rounded-full bg-gradient-to-r from-[color:var(--color-accent)]/40 via-[color:var(--color-gold)]/30 to-[color:var(--color-red)]/40">
                {s.target != null && s.target >= s.lo! && s.target <= s.hi! && (
                  <div className="absolute -top-1 w-0.5 h-3.5 bg-[color:var(--color-cyan)]" style={{ left: `${((s.target - s.lo!) / (s.hi! - s.lo!)) * 100}%` }} title={t('pp.targetTip', { x: money(s.target) })} />
                )}
                <div
                  className="absolute -top-[3px] w-3 h-3 rounded-full bg-[color:var(--color-text)] border-2 border-[color:var(--color-surface)] shadow"
                  style={{ left: `calc(${((s.bestNow.price - s.lo!) / (s.hi! - s.lo!)) * 100}% - 6px)` }}
                  title={`now ${money(s.bestNow.price)}`}
                />
              </div>
              <div className="flex justify-between mt-1.5 text-[10px] text-[color:var(--color-text-faint)]" style={{ fontFamily: 'var(--font-mono)' }}>
                <span className="text-[color:var(--color-accent)]">{t('pp.lowest', { x: money(s.lo!) })}</span>
                {s.target != null && <span className="text-[color:var(--color-cyan)]">{t('pp.targetBar', { x: money(s.target) })}</span>}
                <span>{t('pp.highest', { x: money(s.hi!) })}</span>
              </div>
            </div>
          )}

          {/* Where to buy — cheapest first, each opens the store */}
          {s.stores.length >= 1 && (
            <div className="mt-3.5">
              <p className="text-[10px] uppercase tracking-wider text-[color:var(--color-text-faint)] mb-1.5" style={{ fontFamily: 'var(--font-mono)' }}>{t('it.whereToBuy')}</p>
              <div className="space-y-1">
                {s.stores.slice(0, 5).map((st, i) => (
                  <a key={i} href={st.url} target="_blank" rel="noopener noreferrer"
                    className="flex items-center gap-2 text-xs rounded-lg px-2.5 py-1.5 bg-[color:var(--color-surface-2)] hover:bg-[color:var(--color-surface-3)] transition-colors group">
                    <span className={`w-1.5 h-1.5 rounded-full ${i === 0 ? 'bg-[color:var(--color-accent)]' : 'bg-[color:var(--color-text-faint)]'}`} />
                    <span className="flex-1 truncate text-[color:var(--color-text-dim)]">{st.store}</span>
                    {i === 0 && s.stores.length > 1 && <span className="text-[9px] font-bold text-[color:var(--color-accent)] uppercase">{t('pp.cheapest')}</span>}
                    <span className="font-bold text-[color:var(--color-text)]" style={{ fontFamily: 'var(--font-mono)' }}>{money(st.price)}</span>
                    <ExternalLink size={11} className="text-[color:var(--color-text-faint)] group-hover:text-[color:var(--color-cyan)]" />
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Target (inline editable) + Log a price */}
          <div className="mt-3.5 flex items-center gap-3 flex-wrap text-xs">
            {editTarget ? (
              <span className="flex items-center gap-1.5">
                <Target size={13} className="text-[color:var(--color-cyan)]" />
                <input autoFocus type="number" value={targetVal} onChange={(e) => setTargetVal(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && saveTarget()}
                  placeholder={t('pp.targetPlaceholder', { cur: cur() })} className="w-24 text-xs px-2 py-1 rounded-lg bg-[color:var(--color-surface-2)] border border-[color:var(--color-cyan)] outline-none" style={{ fontFamily: 'var(--font-mono)' }} />
                <button onClick={saveTarget} disabled={pending} className="text-[color:var(--color-accent)]"><Check size={14} /></button>
                <button onClick={() => { setEditTarget(false); setTargetVal(s.target ? String(s.target) : ''); }} className="text-[color:var(--color-text-faint)]">{t('common.cancel')}</button>
              </span>
            ) : (
              <button onClick={() => setEditTarget(true)} className="flex items-center gap-1.5 text-[color:var(--color-text-dim)] hover:text-[color:var(--color-text)] transition-colors">
                <Target size={13} className="text-[color:var(--color-cyan)]" />
                {s.target ? (
                  <>{t('it.targetWord')} <b className="text-[color:var(--color-text)]">{money(s.target)}</b>{toGo != null && (toGo <= 0 ? <span className="text-[color:var(--color-accent)]"> · {t('pp.reached')}</span> : <span className="text-[color:var(--color-text-faint)]"> · {t('pp.toGo', { x: money(toGo) })}</span>)}</>
                ) : (
                  <>{t('pp.setTarget')}</>
                )}
                <Pencil size={11} className="text-[color:var(--color-text-faint)]" />
              </button>
            )}

            <div className="ml-auto flex items-center gap-3">
              {linkCount >= 1 && (
                <button onClick={runRefresh} disabled={refreshing} title={t('pp.refreshTitle')} className="flex items-center gap-1 text-[color:var(--color-text-dim)] hover:text-[color:var(--color-accent)] transition-colors disabled:opacity-50">
                  {refreshing ? <Loader2 size={13} className="animate-spin" /> : <RefreshCw size={13} />} {refreshing ? t('pp.refreshing') : t('pp.refreshPrices')}
                </button>
              )}
              {onSearchOnline && (
                <button onClick={onSearchOnline} className="flex items-center gap-1 text-[color:var(--color-text-dim)] hover:text-[color:var(--color-accent)] transition-colors">
                  <Search size={13} /> {t('pp.searchOnline')}
                </button>
              )}
              {!logging && (
                <button onClick={() => setLogging(true)} className="flex items-center gap-1 text-[color:var(--color-text-dim)] hover:text-[color:var(--color-accent)] transition-colors">
                  <Plus size={13} /> {t('pp.logPrice')}
                </button>
              )}
            </div>
          </div>

          {/* Refresh-prices diff — per tracked store: down / up / unchanged / error */}
          {refreshResults && (
            <div className="mt-2.5 space-y-1">
              {refreshResults.map((r, i) => (
                <div key={i} className="flex items-center gap-2 text-[11px]" style={{ fontFamily: 'var(--font-mono)' }}>
                  {r.changed === 'error' ? (
                    <AlertTriangle size={11} className="text-[color:var(--color-gold)] shrink-0" />
                  ) : r.changed === 'down' ? (
                    <ArrowDown size={11} className="text-[color:var(--color-accent)] shrink-0" />
                  ) : r.changed === 'up' ? (
                    <ArrowUp size={11} className="text-[color:var(--color-gold)] shrink-0" />
                  ) : (
                    <Check size={11} className="text-[color:var(--color-text-faint)] shrink-0" />
                  )}
